formats.schema:
// Android boot image (boot.img) — the partition holding the kernel, ramdisk and
// kernel command line on an Android device. Header versions 0, 1 and 2 share a
// prefix; the later fields appear only when headerVersion says so.
//
// Every section is padded up to pageSize, so the kernel starts at pageSize, the
// ramdisk at the next page boundary after it, and so on.

struct AndroidBoot {
    magic          char[8]    "ANDROID!"
    kernelSize     u32        "kernel size in bytes"
    kernelAddr     u32        "physical load address of the kernel"
    ramdiskSize    u32        "ramdisk size in bytes (0 if none)"
    ramdiskAddr    u32        "physical load address of the ramdisk"
    secondSize     u32        "second stage size in bytes (rarely used)"
    secondAddr     u32        "physical load address of the second stage"
    tagsAddr       u32        "physical address of the kernel tags or device tree"
    pageSize       u32        "flash page size; every section is padded to it"
    headerVersion  u32        "0, 1 or 2 (older images put a size here)"
    osVersion      u32        "OS version and security patch level, packed"
    name           char[16]   "product name (NUL-padded)"
    cmdline        char[512]  "kernel command line"
    id             bytes[32]  "SHA-1 digest of the image sections, zero padded"
    extraCmdline   char[1024] "command line continued past 512 bytes"

    // --- header version 1 ---
    recoveryDtboSize   u32 if headerVersion >= 1 "recovery DTBO or ACPIO size"
    recoveryDtboOffset u64 if headerVersion >= 1 "offset of the recovery DTBO"
    headerSize         u32 if headerVersion >= 1 "size of this header (1648 or 1660)"

    // --- header version 2 ---
    dtbSize u32 if headerVersion >= 2 "device tree blob size"
    dtbAddr u64 if headerVersion >= 2 "physical load address of the device tree"
}

// The kernel starts at pageSize, and each following section starts at the next
// page boundary after the one before it. Those spans are deliberately not read
// as fields here: a carved header with no payload is a normal thing to look at,
// and pulling in a multi-megabyte kernel would make such a file fail to parse.

// ar - the oldest archive format still in daily use. A static library (.a) is
// one, and so is a Debian package: a .deb is an ar archive of exactly three
// members, debian-binary, control.tar.* and data.tar.*, in that order.
//
// The structure is deliberately plain text. An 8-byte global magic, then each
// member is a 60-byte header of space-padded ASCII fields followed by the file
// contents, padded with a newline to an even offset. There is no index of
// members and no compression; the archive is walked by adding up sizes.
//
// Because every length is ASCII decimal rather than a number, a declarative
// walk cannot use one to size the next field - so this pack decodes the global
// magic and the first member header, which is where the interesting part is
// anyway. For a .deb that first member is debian-binary, whose four bytes of
// contents are the package format version.
//
// Long names are handled differently by each variant, and the name field tells
// you which you have:
//   name/            System V: a real name, terminated by a slash
//   /123             System V: the name is at offset 123 of the // string table
//   //               System V: this member is the string table
//   /                System V: this member is the symbol index
//   __.SYMDEF        BSD and macOS: the symbol index
//   #1/20            BSD: the name is the first 20 bytes of the contents
struct ArMemberHeader {
    name      string[16] "member name, space padded; see the variants above"
    mtime     string[12] "modification time, decimal seconds since the epoch"
    uid       string[6]  "owner user id, decimal"
    gid       string[6]  "owner group id, decimal"
    mode      string[8]  "file mode, octal"
    size      string[10] "member size in bytes, decimal, not counting this header or the padding byte"
    terminator bytes[2]  "60 0A, the backtick-newline that ends every header"
}

struct ArArchive {
    magic  string[8]       "!<arch> followed by a newline"
    first  ArMemberHeader  "header of the first member; for a .deb, debian-binary"
}

// The NeXT/Sun audio file - six big-endian 32-bit words and then the samples.
// It is the simplest of the classic audio containers, and the reason so much
// telephony audio is 8 kHz mu-law: that is this format's default shape.
//
// Two fields are allowed to say I do not know. dataSize may be 0xFFFFFFFF when
// the length was not known at write time (audio piped to a file), in which case
// the data runs to the end of the file. dataOffset is at least 24 and doubles
// as the length of the header: any bytes between the last field below and
// dataOffset are the annotation, a free-form, usually NUL-padded comment.

enum AuEncoding : u32 {
    Mulaw8      = 1  // 8-bit ISDN mu-law, the telephony default
    LinearPcm8  = 2  // 8-bit signed linear PCM
    LinearPcm16 = 3  // 16-bit signed linear PCM
    LinearPcm24 = 4  // 24-bit signed linear PCM
    LinearPcm32 = 5  // 32-bit signed linear PCM
    Float32     = 6  // 32-bit IEEE floating point
    Float64     = 7  // 64-bit IEEE floating point
    Fragmented  = 8  // fragmented sampled data
    Dsp         = 10 // DSP program
    Fixed8      = 11 // 8-bit fixed point
    Fixed16     = 12 // 16-bit fixed point
    Fixed24     = 13 // 24-bit fixed point
    Fixed32     = 14 // 32-bit fixed point
    Emphasis16  = 18 // 16-bit linear with emphasis
    Compressed16 = 19 // 16-bit linear, compressed
    EmphasisCompressed16 = 20 // 16-bit linear with emphasis and compression
    DspCommands = 21 // Music Kit DSP commands
    G721Adpcm   = 23 // 4-bit ISDN mu-law, G.721 ADPCM
    G722        = 24 // ISDN mu-law, G.722 ADPCM
    G723_3      = 25 // 3-bit ISDN mu-law, G.723 ADPCM
    G723_5      = 26 // 5-bit ISDN mu-law, G.723 ADPCM
    Alaw8       = 27 // 8-bit ISDN A-law
}

struct Au {
    magic      bytes[4]   "2E 73 6E 64, the ASCII .snd"
    dataOffset u32        "file offset of the audio; also the header length, at least 24"
    dataSize   u32        "bytes of audio, or 0xFFFFFFFF when the length was unknown"
    encoding   AuEncoding "how each sample is stored"
    sampleRate u32        "frames per second (8000 for telephony, 44100 for CD audio)"
    channels   u32        "interleaved channel count (1 mono, 2 stereo)"
    // Whatever sits between here and dataOffset is the annotation; the audio
    // itself starts at dataOffset.
    annotationLen = dataOffset - 24
    annotation bytes[annotationLen] "free-form comment, usually NUL-padded, filling the header out to dataOffset"
}

// RIFF / AVI — little-endian. A generic first-level RIFF chunk walker.
// Note: RIFF pads odd-sized chunks to even boundaries; this walker assumes
// even-sized chunks (true for LIST/movi/idx1 in practice).
struct RiffChunk {
    id   char[4]    "chunk FourCC (LIST, movi, idx1, ...)"
    size u32        "payload size in bytes"
    data bytes[size] "payload (LIST chunks nest more chunks inside)"
}
struct Avi {
    magic    char[4] "RIFF"
    fileSize u32     "total file size minus 8 bytes"
    formType char[4] "'AVI ' form type"
    chunks   repeat RiffChunk "top-level RIFF chunks"
}

// bzip2 — "BZh" plus a block-size digit, then blocks. Each block opens with a
// 48-bit magic (pi: 31 41 59 26 53 59) and the CRC-32 of its uncompressed data;
// everything after that is a bit-packed Huffman/BWT stream and later blocks are
// not byte-aligned, so only the first block header is decoded. The stream ends
// with the magic sqrt(pi) (17 72 45 38 50 90) and a combined CRC.

struct Bzip2 {
    magic      string[2] "always BZ"
    version    char      "always h (Huffman)"
    level      char      "block size: 1..9, in units of 100 kB"
    blockMagic bytes[6]  "31 41 59 26 53 59 (a compressed block follows)"
    blockCrc   u32       "CRC-32 of this block's uncompressed data"
    randomised u8        "bit 7: obsolete randomisation flag; the rest is the bit-packed block"
}

// Microsoft Cabinet - the archive behind .msi payloads, Windows updates and
// old setup.exe installers. Its structure is two levels: files are grouped
// into folders, and a folder is one compressed stream. That is what makes CAB
// solid-compressed - several small files in one folder share a dictionary -
// and it is why extracting one file can mean decompressing the ones before it.
//
// The header has three optional tails, each switched on by a flag: a reserve
// area, and the names of the previous and next cabinet when the set spans
// several files. The folder table starts right after them, and the file table
// is followed to coffFiles by pointer, so the two never have to guess at each
// other.
//
// Each CFFOLDER may carry its own reserve area of cbCFFolder bytes. That is
// almost always zero, and the folder table below assumes it; a cabinet written
// by a tool that uses folder reserves needs that length added per entry.

bitfield CabFlags : u16 {
    prevCabinet    0 // this cabinet continues one that came before
    nextCabinet    1 // this cabinet is continued by another
    reservePresent 2 // the reserve fields below are present
}

// typeCompress packs the method into the low nibble and, for LZX and Quantum,
// the window size into the byte above it: 0x1503 is LZX with a 2^21 window.
bitfield CabCompression : u16 {
    method     0..3  // 0 none, 1 MSZIP, 2 Quantum, 3 LZX
    windowBits 8..12 // window size as a power of two, for Quantum and LZX
}

// CFFOLDER - one compressed stream, holding one or more files.
struct CabFolder {
    coffCabStart u32            "file offset of the first CFDATA block of this folder"
    cCFData      u16            "CFDATA blocks in this folder"
    typeCompress CabCompression "compression used for the whole stream"
}

// CFFILE - one file inside a folder, at an offset into the decompressed stream.
struct CabFile {
    cbFile          u32 "uncompressed size of this file"
    uoffFolderStart u32 "offset of this file in the folder decompressed stream"
    iFolder         u16 "folder index; 0xFFFD/0xFFFE/0xFFFF mean it spans cabinets"
    date            u16 "last modification date (MS-DOS packed)"
    time            u16 "last modification time (MS-DOS packed)"
    attribs         u16 "attributes; bit 7 marks the name as UTF-8 rather than CP437"
    name            cstring "file name, backslash separated, NUL-terminated"
}

struct Cab {
    signature    char[4]  "MSCF"
    reserved1    u32      "reserved, zero"
    cbCabinet    u32      "total size of this cabinet file"
    reserved2    u32      "reserved, zero"
    coffFiles    u32      "file offset of the first CFFILE entry"
    reserved3    u32      "reserved, zero"
    versionMinor u8       "3"
    versionMajor u8       "1"
    cFolders     u16      "CFFOLDER entries in this cabinet"
    cFiles       u16      "CFFILE entries in this cabinet"
    flags        CabFlags "which optional fields follow"
    setID        u16      "identifier shared by every cabinet in a set"
    iCabinet     u16      "position of this cabinet in the set, from 0"
    cbCFHeader   u16 if flags.reservePresent "bytes of reserve area in this header"
    cbCFFolder   u8  if flags.reservePresent "bytes of reserve area per folder entry"
    cbCFData     u8  if flags.reservePresent "bytes of reserve area per data block"
    abReserve    bytes[cbCFHeader] if flags.reservePresent "application-defined header reserve"
    szCabinetPrev cstring if flags.prevCabinet "file name of the previous cabinet"
    szDiskPrev    cstring if flags.prevCabinet "name of the disk holding it"
    szCabinetNext cstring if flags.nextCabinet "file name of the next cabinet"
    szDiskNext    cstring if flags.nextCabinet "name of the disk holding it"
    folders       CabFolder[cFolders] "the folder table"
    // The file table, followed to coffFiles. Placed by pointer: the names are
    // variable length, so nothing else could find the end of the table.
    files at coffFiles CabFile[cFiles] "the file table"
}

// Core Audio Format - Apple's replacement for AIFF and WAV, designed to lift
// their limits: sizes are 64-bit signed, so a file is not capped at 4 GB, and
// the sample rate is a double rather than a fixed-point value.
//
// The layout is the familiar chunked one: an 8-byte file header, then chunks of
// a four-character type and a 64-bit size. The Audio Description chunk (desc)
// must come first and is always 32 bytes; everything else may appear in any
// order.
//
// One wrinkle worth knowing: the data chunk's size may be -1, meaning it runs
// to the end of the file. That is only legal for the last chunk, and is what a
// recorder writes while it is still capturing.

bitfield CafFormatFlags : u32 {
    isFloat      0 // samples are floating point rather than integer
    isLittleEndian 1 // samples are little-endian (the format itself stays big-endian)
}

// desc - the Audio Description chunk. Always present, always first, always 32
// bytes. A frame is one sample across all channels; a packet is the codec's
// unit, equal to one frame for uncompressed audio.
struct CafAudioDescription {
    sampleRate      f64             "frames per second, as a double (44100.0, 48000.0)"
    formatId        char[4]         "codec: lpcm, aac , alac, ima4, ulaw, alaw"
    formatFlags     CafFormatFlags  "codec-specific flags; for lpcm, the sample layout"
    bytesPerPacket  u32             "bytes in one packet, 0 when packets vary in size"
    framesPerPacket u32             "frames in one packet, 0 when that varies too"
    channelsPerFrame u32            "channel count (1 mono, 2 stereo)"
    bitsPerChannel  u32             "bits per sample in one channel, 0 for compressed audio"
}

// pakt - the packet table, needed to seek in variable-bit-rate audio. The
// per-packet sizes that follow are variable-length integers, so only the
// counts are decoded here.
struct CafPacketTable {
    numberPackets     i64 "packets in the data chunk"
    numberValidFrames i64 "frames of real audio, excluding codec priming and padding"
    primingFrames     i32 "frames the decoder must run before the output is valid"
    remainderFrames   i32 "frames of padding at the end of the last packet"
}

// data - the audio itself, prefixed by an edit count.
struct CafData {
    editCount u32 "bumped every time the audio is edited; 0 in a fresh file"
}

// info - free-form metadata as a run of NUL-terminated key/value strings.
struct CafInfo {
    numEntries u32 "number of key/value string pairs that follow"
}

// free - padding a writer leaves so metadata can grow without rewriting the
// file. Nothing to decode; the size is the point.

struct CafChunk {
    type char[4]      "four-character chunk type"
    size i64          "bytes of chunk data; -1 on the last chunk means to end of file"
    data bytes[size]  "chunk data"
    // Typed view of the data, placed by pointer so it reads no bytes of its own
    // and the walk above stays exact whatever the type turns out to be.
    decoded at +12 match type {
        "desc" => CafAudioDescription
        "pakt" => CafPacketTable
        "data" => CafData
        "info" => CafInfo
        default => bytes[0]
    }
}

struct Caf {
    fileType    char[4]        "caff"
    fileVersion u16            "format version, 1"
    fileFlags   u16            "no flags are defined for version 1; always 0"
    chunks      repeat CafChunk "every chunk in order, desc first"
}

// Compound File Binary - Microsoft's filesystem in a file, and what a legacy
// .doc, .xls, .ppt, .msi or Outlook .msg actually is. It is also the reason
// those files hide so much: the container has directories, streams, free space
// and slack, all of it inside one file.
//
// The design is FAT, scaled down. The file is an array of sectors, numbered
// from 0 starting immediately after this 512-byte header, each 512 bytes (v3)
// or 4096 bytes (v4). A stream is a chain of sectors, and the FAT is one entry
// per sector giving the next one, with these terminators:
//   0xFFFFFFFF  free            0xFFFFFFFE  end of chain
//   0xFFFFFFFD  a FAT sector    0xFFFFFFFC  a DIFAT sector
//
// The FAT itself is stored in sectors, and the list of those sectors is the
// DIFAT. Its first 109 entries live in this header, which covers roughly 6.8 MB
// in a v3 file; larger files chain further DIFAT sectors from difatFirstSector.
//
// Streams smaller than miniStreamCutoff (4096 bytes by default) do not get a
// sector each. They are packed into the mini stream and allocated by the MiniFAT
// in 64-byte mini sectors - which is where small streams, and their slack, end
// up.
//
// Directory entries are 128 bytes each, so 4 to a v3 sector. Entry 0 is the
// root, whose stream is the mini stream. The entries form a red-black tree per
// directory, which is why each one carries sibling and child pointers rather
// than a flat list.

enum CfbObjectType : u8 {
    Unallocated = 0
    Storage     = 1 // a directory
    Stream      = 2 // a file
    RootEntry   = 5 // the root storage; its stream is the mini stream
}

enum CfbColor : u8 {
    Red   = 0
    Black = 1
}

// One 128-byte directory entry. The name is UTF-16LE and NUL-terminated, and
// the first character is sometimes below 0x20 to mark an internal stream - the
// 0x05 prefix on SummaryInformation, for instance.
struct CfbDirectoryEntry {
    name         bytes[64]     "entry name, UTF-16LE, NUL-terminated"
    nameLength   u16           "bytes of name in use, terminator included"
    objectType   CfbObjectType "storage, stream, or the root"
    colorFlag    CfbColor      "red-black tree colour of this node"
    leftSibling  u32           "directory id of the left sibling, 0xFFFFFFFF for none"
    rightSibling u32           "directory id of the right sibling, 0xFFFFFFFF for none"
    child        u32           "directory id of the first child, for a storage"
    clsid        bytes[16]     "CLSID of the object, for a storage"
    stateBits    u32           "user-defined state flags"
    creationTime u64           "FILETIME: 100-nanosecond ticks since 1601-01-01 UTC"
    modifiedTime u64           "FILETIME of the last modification"
    startSector  u32           "first sector of the stream, or of the mini stream for the root"
    streamSize   u64           "stream length in bytes"
}

struct CfbDirectorySector {
    entries CfbDirectoryEntry[4] "the first four entries; the root is entry 0"
}

struct Cfb {
    signature         bytes[8]  "D0 CF 11 E0 A1 B1 1A E1"
    clsid             bytes[16] "unused, zero"
    minorVersion      u16       "0x003E in practice"
    majorVersion      u16       "3 for 512-byte sectors, 4 for 4096-byte sectors"
    byteOrder         u16       "0xFFFE, marking little-endian"
    sectorShift       u16       "sector size as a power of two: 9 means 512 bytes, 12 means 4096"
    miniSectorShift   u16       "mini sector size as a power of two; always 6, so 64 bytes"
    reserved          bytes[6]  "reserved, zero"
    numDirSectors     u32       "sectors in the directory chain; 0 in a v3 file"
    numFatSectors     u32       "sectors making up the FAT"
    firstDirSector    u32       "first sector of the directory chain"
    transactionSignature u32    "incremented by transactioned writers; 0 otherwise"
    miniStreamCutoff  u32       "streams below this size live in the mini stream; always 4096"
    firstMiniFatSector u32      "first sector of the MiniFAT chain"
    numMiniFatSectors u32       "sectors making up the MiniFAT"
    difatFirstSector  u32       "first DIFAT sector, when the 109 entries below are not enough"
    numDifatSectors   u32       "sectors making up the rest of the DIFAT"
    difat             u32[109]  "the first 109 FAT sector numbers; unused slots are 0xFFFFFFFF"
    // Sector n starts at (n + 1) * sectorSize, because sector 0 follows this
    // 512-byte header - so where the directory begins depends on sectorShift.
    // Both sector sizes are followed here; only the one this file uses appears.
    dirOffsetV3 = firstDirSector * 512 + 512
    dirOffsetV4 = firstDirSector * 4096 + 4096
    rootDirectoryV3 at dirOffsetV3 CfbDirectorySector if sectorShift == 9 "first directory sector, 512-byte sectors: the root entry, then the first storages and streams"
    rootDirectoryV4 at dirOffsetV4 CfbDirectorySector if sectorShift == 12 "first four entries of the first directory sector; a 4096-byte sector holds 32 of them"
}

// A Chrome extension is a zip archive with a signature stapled to the front.
// The point of the header is provenance: the extension id is derived from the
// public key in it, so the same key always produces the same id, and an update
// signed by a different key is rejected.
//
// Two versions exist, and they lay the header out differently. CRX2 puts a raw
// RSA public key and a signature in the header. CRX3 replaced that with a
// protobuf message (CrxFileHeader) holding one or more proofs, each a key and a
// signature, which is what allows a package to be signed by both the developer
// and the store.
//
// In both cases the zip begins immediately after the header, so an extension
// can be unzipped by skipping it - and the zip is where the manifest.json and
// the extension's code live.

struct Crx2Header {
    publicKeyLength u32 "bytes of RSA public key, DER encoded SubjectPublicKeyInfo"
    signatureLength u32 "bytes of RSA SHA-1 signature over the zip"
    publicKey bytes[publicKeyLength] "the developer public key the extension id is derived from"
    signature bytes[signatureLength] "signature over the zip that follows"
}

struct Crx3Header {
    headerLength u32 "bytes of CrxFileHeader protobuf that follow"
    header bytes[headerLength] "CrxFileHeader: signed_header_data plus one proof per signing key"
}

struct Crx {
    magic   char[4]     "Cr24"
    version u32         "2 or 3; 3 is what Chrome has published since 2017"
    crx2    Crx2Header  if version == 2 "raw key and signature"
    crx3    Crx3Header  if version == 3 "protobuf header carrying the signing proofs"
    // The zip archive starts here: manifest.json, then the extension's files.
    zip     bytes[*]    "the extension payload, a zip archive"
}

// DICOM - the file every medical scanner writes, and the reason a CT study can
// be read on any workstation. A Part 10 file is deliberately front-loaded: 128
// bytes of preamble that DICOM itself does not use (some applications hide a
// TIFF or JPEG header there so the file also opens as a picture), the four
// bytes DICM, and then the file meta information group.
//
// Everything in the file meta group is encoded as explicit VR little-endian, by
// rule, whatever the rest of the file uses. That matters, because one element
// inside it - TransferSyntaxUID, tag (0002,0010) - names the encoding of the
// data set that follows. Read it before trusting any byte after the meta group:
//   1.2.840.10008.1.2        implicit VR little-endian (no VR field per element)
//   1.2.840.10008.1.2.1      explicit VR little-endian, the common case
//   1.2.840.10008.1.2.2      explicit VR big-endian, retired
//   1.2.840.10008.1.2.4.50   JPEG baseline, lossy
//   1.2.840.10008.1.2.4.70   JPEG lossless
//   1.2.840.10008.1.2.4.90   JPEG 2000 lossless
//   1.2.840.10008.1.2.5      RLE lossless
//
// An element is a group number, an element number, a two-letter value
// representation, a length, and a value. Most VRs carry a 16-bit length; the
// binary and sequence VRs (OB, OW, OF, OD, OL, OV, SQ, UC, UR, UT, UN) carry
// two reserved bytes and a 32-bit length instead. Inside the meta group the
// only long-form element is FileMetaInformationVersion, which is why it is
// decoded on its own below.
//
// The data set is left as bytes: without acting on the transfer syntax above,
// a declarative walk cannot know whether its elements even have VR fields.

// (0002,0000) FileMetaInformationGroupLength - always first, always this exact
// shape, and the only way to find where the data set starts.
struct DicomGroupLength {
    group       u16     "0x0002, the file meta group"
    element     u16     "0x0000, the group length element"
    vr          char[2] "UL, a 32-bit unsigned long"
    length      u16     "4"
    groupLength u32     "bytes of file meta group following this element"
}

// (0002,0001) FileMetaInformationVersion - an OB element, so it takes the
// long form: two reserved bytes and a 32-bit length.
struct DicomMetaVersion {
    group    u16     "0x0002"
    element  u16     "0x0001"
    vr       char[2] "OB, other byte - a binary VR, so the length is 32-bit"
    reserved u16     "reserved, zero"
    length   u32     "2"
    version  bytes[2] "00 01"
}

// A short-form element: the shape every remaining meta element uses.
struct DicomElement {
    group   u16          "group number; 0x0002 for the file meta group"
    element u16          "element number within the group"
    vr      char[2]      "value representation: UI a UID, SH short text, AE an application entity title"
    length  u16          "bytes of value; always even, padded if need be"
    value   bytes[length] "the value, laid out as the VR dictates"
}

// The meta elements after the version, decoded as a group. The walk ends on the
// first element whose group is above 0x0002 - that entry is the boundary marker,
// the start of the data set read under meta-group rules, not meta information.
struct DicomMetaElements {
    elements repeat DicomElement until group > 2 "media storage SOP class and instance UIDs, transfer syntax, implementation identifiers"
}

struct Dicom {
    preamble  bytes[128]       "128 bytes DICOM ignores; zero, unless an application hid an image header here"
    magic     char[4]          "DICM"
    groupLen  DicomGroupLength "(0002,0000) - how long the file meta group is"
    version   DicomMetaVersion "(0002,0001) - the one long-form element in the meta group"
    // The rest of the meta group, counted exactly by the group length, with a
    // decoded view placed over it by pointer so the byte accounting stays exact.
    restLen = groupLen.groupLength - 14
    metaGroup bytes[restLen]   "the remaining file meta elements"
    decoded   at +158 DicomMetaElements "those elements, decoded"
    dataset   bytes[*]         "the data set: patient, study, series and pixel data, in the transfer syntax named above"
}

// Flattened device tree (devicetree specification chapter 5) — the .dtb the
// Linux kernel and U-Boot consume, and the container of U-Boot FIT images.
// Big-endian throughout: a 40-byte header, a memory reservation map, the
// structure block (a token stream of BEGIN_NODE / PROP / END_NODE) and a
// strings block holding the property names.
//
// The structure block is walked token by token. Node names are NUL-terminated
// and padded to 4 bytes; the name is decoded by pointer and the padded span is
// consumed in 4-byte chunks until one contains the terminating NUL. Property
// names are offsets into the strings block, which is listed in full.

enum FdtToken : u32 {
    BeginNode = 1
    EndNode   = 2
    Prop      = 3
    Nop       = 4
    End       = 9
}

// One reserved physical memory range; the map ends with an all-zero entry.
struct FdtReserveEntry {
    address u64 "physical start address"
    size    u64 "size in bytes (0 with address 0 terminates the map)"
}

// A 4-byte chunk of a padded node name; the last chunk ends in NUL padding.
struct FdtNameChunk {
    text     string[4] "up to four name characters"
    lastByte at +3 u8  "final byte: 0 in the chunk that ends the name"
}

struct FdtBeginNode {
    name   at +0 cstring "node name (empty for the root node)"
    chunks repeat FdtNameChunk until lastByte == 0 "the name plus its padding, in 4-byte steps"
}

struct FdtProp {
    len     u32        "property value length in bytes"
    nameOff u32        "offset of the property name in the strings block"
    value   bytes[len] "property value (cells, strings or bytes)"
    padLen  = (4 - len % 4) % 4
    pad     bytes[padLen] "alignment padding to 4 bytes"
}

struct FdtStructToken {
    token FdtToken "structure block token"
    body  match token {
        1       => FdtBeginNode
        3       => FdtProp
        default => bytes[0]
    }
}

// One NUL-terminated property name in the strings block.
struct FdtString {
    name cstring "property name"
}

struct Fdt {
    magic           u32 "0xD00DFEED"
    totalSize       u32 "total size of the blob in bytes"
    offDtStruct     u32 "offset of the structure block"
    offDtStrings    u32 "offset of the strings block"
    offMemRsvmap    u32 "offset of the memory reservation map"
    version         u32 "format version (17)"
    lastCompVersion u32 "lowest compatible version (16)"
    bootCpuidPhys   u32 "physical id of the boot CPU"
    sizeDtStrings   u32 "size of the strings block"
    sizeDtStruct    u32 "size of the structure block"
    reserveMap at offMemRsvmap repeat FdtReserveEntry until size == 0 "reserved memory ranges, terminated by a zero entry"
    structure  at offDtStruct  repeat FdtStructToken  until token == 9 "the device tree itself, as tokens"
    strings    at offDtStrings bytes[sizeDtStrings] "strings block: NUL-terminated property names"
    stringList at offDtStrings repeat FdtString "property names (the strings block is normally last in the file)"
}

// EVTX - the event log Windows has written since Vista, and one of the first
// files pulled in an intrusion investigation. Its shape is a circular buffer:
// a 4 KiB file header, then a run of 64 KiB chunks, each self-contained with
// its own record range and checksums. When the log fills, the oldest chunk is
// overwritten rather than the file being rewritten, which is why the record
// numbers in the header matter more than the chunk order on disk.
//
// That design is also what makes a truncated or carved EVTX recoverable: any
// surviving "ElfChnk" block can be parsed on its own, because a chunk carries
// the string and template tables its records refer to.
//
// The records themselves are BinXML - a binary encoding of the event XML,
// using per-chunk templates so repeated events store only their substitutions.
// Decoding that needs a tokeniser, so records are left as bytes here; the
// chunk headers below give the record numbers, offsets and checksums.

bitfield EvtxFileFlags : u32 {
    dirty 0 // records were written since the log was last cleanly closed
    full  1 // the log has wrapped at least once
}

struct EvtxChunk {
    magic                  char[8]   "ElfChnk, NUL-terminated"
    firstEventRecordNumber u64       "logical number of the first record in this chunk"
    lastEventRecordNumber  u64       "logical number of the last record"
    firstEventRecordId     u64       "file-wide identifier of the first record"
    lastEventRecordId      u64       "file-wide identifier of the last record"
    headerSize             u32       "128"
    lastRecordOffset       u32       "offset of the last record, from the chunk start"
    freeSpaceOffset        u32       "offset of the free space after the last record"
    eventRecordsChecksum   u32       "CRC-32 over the records area"
    unused                 bytes[64] "zero"
    unknown                u32       "flags, in practice zero"
    checksum               u32       "CRC-32 of the first 120 bytes and the tables below"
    commonStringOffsets    u32[64]   "hash buckets into the per-chunk string table"
    templatePointers       u32[32]   "hash buckets into the per-chunk template table"
    records                bytes[65024] "the BinXML event records filling the rest of the chunk"
}

struct Evtx {
    magic             char[8]  "ElfFile, NUL-terminated"
    firstChunkNumber  u64      "first chunk still in use, after any rollover"
    lastChunkNumber   u64      "last chunk in use"
    nextRecordId      u64      "identifier the next record written will get"
    headerSize        u32      "128"
    minorVersion      u16      "1"
    majorVersion      u16      "3"
    headerBlockSize   u16      "4096: the header occupies a full block"
    chunkCount        u16      "chunks in the file"
    unused            bytes[76] "zero"
    fileFlags         EvtxFileFlags "dirty and wrapped flags"
    checksum          u32      "CRC-32 of the first 120 bytes"
    padding           bytes[3968] "zero, to the end of the 4 KiB header block"
    chunks            repeat EvtxChunk "every 64 KiB chunk, in file order"
}

// FAT12/16 boot sector - the first sector of the volume, holding both the boot
// code and the BIOS parameter block that describes the geometry. The BPB is
// what a driver reads: sector size, cluster size, how many copies of the
// allocation table there are, and where the root directory sits.
//
// FAT12 and FAT16 differ only in the width of an entry in the table, and the
// sector cannot tell you which it is. The rule is by cluster count: fewer than
// 4085 clusters is FAT12, fewer than 65525 is FAT16, anything more is FAT32.
//
// The layout has an odd shape because it grew: the BPB starts three bytes in,
// after a jump instruction, and several fields are duplicated in 16- and
// 32-bit form because the original ones overflowed on larger disks.

enum FatMediaDescriptor : u8 {
    Floppy144M   = 0xF0
    FixedDisk    = 0xF8
    Floppy720K   = 0xF9
    Floppy320K   = 0xFA
    Floppy640K   = 0xFB
    Floppy180K   = 0xFC
    Floppy360K   = 0xFD
    Floppy160K   = 0xFE
    Floppy320KAlt = 0xFF
}

struct Fat16 {
    jump             bytes[3] "a short jump over the BPB to the boot code"
    oemName          char[8]  "formatting system; MSDOS5.0 or mkfs.fat on Linux"
    bytesPerSector   u16      "512 on essentially everything"
    sectorsPerCluster u8      "cluster size, a power of two"
    reservedSectors  u16      "sectors before the first allocation table, this one included"
    numberOfFats     u8       "copies of the allocation table, normally 2"
    rootEntries      u16      "entries in the fixed-size root directory"
    totalSectors16   u16      "sectors on the volume, 0 when it needs 32 bits"
    mediaDescriptor  FatMediaDescriptor "media type, echoed in the first FAT entry"
    sectorsPerFat    u16      "sectors in one allocation table"
    sectorsPerTrack  u16      "disk geometry, for the BIOS"
    numberOfHeads    u16      "disk geometry, for the BIOS"
    hiddenSectors    u32      "sectors before this partition on the disk"
    totalSectors32   u32      "sectors on the volume, when it does not fit in 16 bits"
    driveNumber      u8       "BIOS drive: 0x00 floppy, 0x80 hard disk"
    reserved         u8       "reused by Windows NT as a dirty flag"
    bootSignature    u8       "0x29 when the three fields below are present"
    volumeSerial     u32      "serial number, generated at format time"
    volumeLabel      char[11] "volume label, space padded; also stored in the root directory"
    fileSystemType   char[8]  "FAT12 or FAT16, space padded; advisory only"
    bootCode         bytes[448] "the boot code the jump above lands in"
    endMarker        u16      "0xAA55, the sector signature"
}

// FLAC — big-endian. Magic then a metadata-block stream ending at the block
// whose header 'last' bit is set. Block lengths are 24-bit big-endian, read as
// three bytes and recombined (the DSL has no u24 primitive).
bitfield FlacBlockHeader : u8 {
    lastBlock 7
    blockType 0..6
}
struct FlacBlock {
    header FlacBlockHeader "bit7 = last block, bits0-6 = type (0 = STREAMINFO)"
    lenHi  u8              "length byte (high)"
    lenMid u8              "length byte (mid)"
    lenLo  u8              "length byte (low)"
    length = lenHi * 65536 + lenMid * 256 + lenLo
    data   bytes[length]   "metadata block contents"
}
struct Flac {
    magic  char[4] "magic 'fLaC'"
    blocks repeat FlacBlock until header.lastBlock "metadata blocks"
}

// FLV - a nine-byte header and then a flat chain of tags, each carrying one
// audio frame, one video frame, or a chunk of AMF script data. Big-endian
// throughout, and every size and timestamp is 24 bits, so they are read as
// three bytes and recombined (the DSL has no u24 primitive).
//
// Each tag is preceded by the size of the tag before it. That backward link is
// what lets a player seek backwards through a stream, and it is why the first
// tag is preceded by a zero.
//
// The first byte of an audio or video tag packs the codec and its parameters
// into nibbles, decoded below as bitfields.

bitfield FlvHeaderFlags : u8 {
    video 0
    audio 2
}

enum FlvTagType : u8 {
    Audio      = 8
    Video      = 9
    ScriptData = 18
}

bitfield FlvAudioHeader : u8 {
    soundFormat 4..7 // 0 linear PCM, 2 MP3, 10 AAC, 11 Speex
    soundRate   2..3 // 0 5.5 kHz, 1 11 kHz, 2 22 kHz, 3 44 kHz
    soundSize   1    // 0 = 8-bit samples, 1 = 16-bit
    soundType   0    // 0 = mono, 1 = stereo
}

bitfield FlvVideoHeader : u8 {
    frameType 4..7 // 1 keyframe, 2 inter frame, 5 video info/command
    codecId   0..3 // 2 Sorenson H.263, 4 VP6, 7 AVC (H.264)
}

struct FlvAudioTag {
    header FlvAudioHeader "codec, sample rate, sample size and channel count"
}

struct FlvVideoTag {
    header FlvVideoHeader "frame type and codec"
}

struct FlvTag {
    previousTagSize u32        "size of the tag before this one; 0 for the first"
    tagType         FlvTagType "audio, video, or AMF script data"
    sizeHi          u8         "data size byte (high)"
    sizeMid         u8         "data size byte (mid)"
    sizeLo          u8         "data size byte (low)"
    dataSize        = sizeHi * 65536 + sizeMid * 256 + sizeLo
    timeHi          u8         "timestamp byte (high)"
    timeMid         u8         "timestamp byte (mid)"
    timeLo          u8         "timestamp byte (low)"
    timestamp       = timeHi * 65536 + timeMid * 256 + timeLo
    timestampExt    u8         "the timestamp upper byte: the real value is 32-bit"
    streamIdHi      u8         "stream id byte (high), always 0"
    streamIdMid     u8         "stream id byte (mid), always 0"
    streamIdLo      u8         "stream id byte (low), always 0"
    data            bytes[dataSize] "the tag payload"
    // Typed view of the first payload byte. Placed by pointer, so it reads no
    // bytes of its own and the tag walk above stays exact.
    decoded at +15 match tagType {
        8  => FlvAudioTag
        9  => FlvVideoTag
        default => bytes[0]
    }
}

struct Flv {
    signature  char[3]        "FLV"
    version    u8             "1"
    flags      FlvHeaderFlags "which streams the file contains"
    dataOffset u32            "header size in bytes; 9 in every version so far"
    tags       repeat FlvTag  "every tag, in timestamp order"
}

// The Game Boy Advance cartridge header - 192 bytes at the start of the ROM,
// mapped by the console at 0x08000000. It is a good example of a header used as
// a lock: the BIOS checks the Nintendo logo and the header checksum before it
// will run the cartridge, so both had to be exactly right for a game to boot on
// real hardware.
//
// The first field is an ARM branch instruction rather than an address. The BIOS
// jumps to 0x08000000, executes it, and lands at the game's real entry point.
// A multiboot image - code sent to a second console over the link cable - has a
// second such branch at offset 0xC0.
//
// The game code is structured: U or A for the type, two characters of short
// title, then the region - E North America, J Japan, P Europe, D Germany,
// F France, S Spain, I Italy. That is the code printed on the cartridge label,
// and what a ROM database looks a game up by.
//
// headerChecksum is the one field a ROM hacker has to recompute: it is the
// 8-bit sum of the bytes from 0xA0 to 0xBC, negated, minus 0x19.

struct GbaRom {
    entryPoint    u32       "an ARM branch instruction to the real entry point, not an address"
    nintendoLogo  bytes[156] "the compressed Nintendo logo; the BIOS refuses to boot if a byte differs"
    gameTitle     string[12] "game title, uppercase ASCII, NUL-padded"
    gameCode      string[4]  "type, two title characters, then the region letter"
    makerCode     string[2]  "publisher code; 01 is Nintendo"
    fixed         u8         "must be 0x96"
    mainUnitCode  u8         "hardware the cartridge is for; 0 is a retail GBA"
    deviceType    u8         "0 normally, 0x80 for a debugging cartridge with more RAM"
    reserved      bytes[7]   "reserved, zero"
    softwareVersion u8       "game version, counting from 0"
    headerChecksum u8        "8-bit checksum over the bytes from gameTitle to reserved2"
    reserved2     bytes[2]   "reserved, zero"
    // A multiboot image continues with a second entry branch at 0xC0, a boot
    // mode byte and a slave id; a normal cartridge starts its code here.
}

// glTF binary (.glb) — little-endian 12-byte header + a chunk stream.
struct GlbChunk {
    length    u32     "chunk data length in bytes"
    chunkType char[4] "JSON structure chunk, or the BIN binary buffer chunk"
    data match chunkType {
        "JSON"  => string[length]
        default => bytes[length]
    }
}
struct Glb {
    magic   char[4] "magic 'glTF'"
    version u32     "GLB container version (2)"
    length  u32     "total length of the file in bytes"
    chunks  repeat GlbChunk "JSON chunk then BIN chunk"
}

// gzip - a ten-byte fixed header, a handful of optional fields the flags
// switch on, then the raw deflate stream. A file is really a sequence of
// members, each with its own header; concatenating two .gz files is a valid
// .gz file, which is how tools like pigz write in parallel.
//
// The CRC-32 and the uncompressed size live in an eight-byte trailer at the
// very end of each member. They are not shown here: reaching them means
// decompressing the deflate stream, which a declarative schema cannot do.
// The `deflate` field below therefore runs to the end of the data.

bitfield GzipFlags : u8 {
    text     0 // the compressed data is probably ASCII text
    hcrc     1 // a CRC-16 of the header follows the optional fields
    extra    2 // an extra field is present
    name     3 // the original file name is present
    comment  4 // a comment is present
}

enum GzipOs : u8 {
    Fat         = 0
    Amiga       = 1
    Vms         = 2
    Unix        = 3
    VmCms       = 4
    AtariTos    = 5
    Hpfs        = 6
    Macintosh   = 7
    ZSystem     = 8
    CpM         = 9
    Tops20      = 10
    Ntfs        = 11
    Qdos        = 12
    AcornRiscOs = 13
    Unknown     = 255
}

struct Gzip {
    magic      bytes[2]   "1F 8B"
    method     u8         "compression method; 8 = deflate, the only one defined"
    flags      GzipFlags  "which optional fields follow the fixed header"
    mtime      u32        "modification time of the original file (unix), 0 if unset"
    extraFlags u8         "2 = compressed with the best algorithm, 4 = with the fastest"
    os         GzipOs     "filesystem the file came from"
    extraLen   u16              if flags.extra   "length of the extra field"
    extra      bytes[extraLen]  if flags.extra   "extra field: subfield id, length, data"
    name       cstring          if flags.name    "original file name, NUL-terminated"
    comment    cstring          if flags.comment "comment, NUL-terminated"
    headerCrc  u16              if flags.hcrc    "low 16 bits of the CRC-32 of the header"
    deflate    bytes[*]   "the deflate stream, then an 8-byte CRC-32 and size trailer"
}

// HFS+ - the Mac filesystem from 1998 until APFS replaced it, and still what a
// plain .dmg or an old Time Machine disk contains. Big-endian, because it was
// designed for 68k and PowerPC Macs.
//
// The volume header sits 1024 bytes into the volume, leaving room for two boot
// blocks, and a copy of it sits 1024 bytes before the end. Point this at a raw
// partition image or a decompressed .dmg.
//
// What makes HFS+ distinctive is that its own metadata lives in ordinary files,
// described by the five forks at the end of this header. The catalog file is a
// B-tree of every file and folder record; the extents overflow file holds the
// extent lists too long to fit in a catalog record; the allocation file is the
// block bitmap; the attributes file holds extended attributes, and is where a
// compressed file's data ends up. A fork is described by eight extents inline,
// each a start block and a length - further extents go in the overflow file.
//
// Timestamps are seconds since 1904-01-01, the classic Mac epoch, and are in
// local time in this header (the one place HFS+ does that) except for
// createDate, which is UTC.
//
// The signature also tells the two variants apart: H+ is HFS+ with a
// case-insensitive catalog, HX is HFSX, which may be case sensitive.

bitfield HfsVolumeAttributes : u32 {
    hardwareLock      7  // mounted read-only by hardware
    unmounted         8  // cleanly unmounted; if clear, the volume needs a check
    sparedBlocks      9  // bad blocks have been spared into the bad block file
    noCacheRequired   10 // the volume is on a device that should not be cached
    bootVolumeInconsistent 11 // set on mount, cleared on unmount: a dirty flag
    catalogNodeIdsReused 12 // the catalog node id counter has wrapped
    journaled         13 // the volume has a journal; journalInfoBlock is valid
    softwareLock      15 // mounted read-only by software
}

// One extent: a run of contiguous allocation blocks.
struct HfsExtent {
    startBlock u32 "first allocation block of the run"
    blockCount u32 "length of the run in allocation blocks"
}

// A fork: its size, and the first eight extents of its contents.
struct HfsForkData {
    logicalSize u64          "size of the fork in bytes"
    clumpSize   u32          "bytes to grow this fork by when it needs more space"
    totalBlocks u32          "allocation blocks the fork occupies"
    extents     HfsExtent[8] "the first eight extents; the rest live in the extents overflow file"
}

struct HfsPlus {
    bootBlocks         bytes[1024]         "two boot blocks, not part of the filesystem metadata"
    signature          char[2]             "H+ for HFS+, HX for HFSX"
    version            u16                 "4 for HFS+, 5 for HFSX"
    attributes         HfsVolumeAttributes "volume flags"
    lastMountedVersion char[4]             "implementation that last mounted the volume: 10.0 for macOS, HFSJ when journaled, fsck for a repair"
    journalInfoBlock   u32                 "allocation block holding the journal info, when journaled"
    createDate         u32                 "volume creation time, seconds since 1904-01-01, UTC"
    modifyDate         u32                 "last modification, local time"
    backupDate         u32                 "last backup, local time"
    checkedDate        u32                 "last consistency check, local time"
    fileCount          u32                 "files on the volume, not counting the special files"
    folderCount        u32                 "folders, not counting the root"
    blockSize          u32                 "allocation block size in bytes; 4096 is usual"
    totalBlocks        u32                 "allocation blocks on the volume"
    freeBlocks         u32                 "unused allocation blocks"
    nextAllocation     u32                 "where to start looking for free space"
    rsrcClumpSize      u32                 "default clump size for resource forks"
    dataClumpSize      u32                 "default clump size for data forks"
    nextCatalogId      u32                 "next catalog node id to hand out"
    writeCount         u32                 "bumped every time the volume is mounted for writing"
    encodingsBitmap    u64                 "which text encodings the volume names use"
    finderInfo         u32[8]              "Finder information: blessed system folder and boot directory ids"
    allocationFile     HfsForkData         "the allocation bitmap: one bit per allocation block"
    extentsFile        HfsForkData         "the extents overflow file: extents beyond the eight inline ones"
    catalogFile        HfsForkData         "the catalog: a B-tree of every file and folder record"
    attributesFile     HfsForkData         "extended attributes, including compressed file data"
    startupFile        HfsForkData         "boot loader data for systems that need it; usually empty"
}

// Apple icon image (.icns) — big-endian. An 8-byte header followed by a flat
// stream of icon elements, each one an 8-byte header plus its payload. The
// element type names both the size and the encoding: 'ic07'..'ic14' hold whole
// PNG or JPEG 2000 files, 'is32'/'il32' hold raw RLE-packed RGB, 's8mk'/'l8mk'
// hold 8-bit alpha masks, and 'TOC ' is an optional table of contents.
struct IcnsElement {
    type    char[4]       "element type: icon size and encoding, or 'TOC '"
    size    u32           "element size in bytes, this 8-byte header included"
    dataLen = size - 8
    data    bytes[dataLen] "the icon image, mask, or table of contents"
}

struct Icns {
    magic    char[4] "magic 'icns'"
    fileSize u32     "total file size in bytes, this header included"
    elements repeat IcnsElement "the icon family, one element per size and depth"
}

enum IcoType : u16 {
    Icon   = 1
    Cursor = 2
}

struct IconDirEntry {
    width       u8   "image width in px (0 means 256)"
    height      u8   "image height in px (0 means 256)"
    colorCount  u8   "colors in the palette (0 if 256 or more)"
    reserved    u8   "reserved (0)"
    planes      u16  "color planes (or the cursor hotspot X)"
    bitCount    u16  "bits per pixel (or the cursor hotspot Y)"
    bytesInRes  u32  "size of the image data in bytes"
    imageOffset u32  "offset of the image data from the file start"
}

struct Ico {
    reserved u16     "reserved, always 0"
    type     IcoType "resource type: 1 = icon, 2 = cursor"
    count    u16     "number of images in the file"
    entries  IconDirEntry[count] "the icon directory"
}

// El Torito - the extension that makes a CD bootable. It adds a boot record
// volume descriptor at sector 17, whose only real content is a pointer to the
// boot catalog: a sector of 32-byte entries naming what to boot on which
// platform. That catalog is followed here by pointer.
//
// The initial/default entry is the one a BIOS uses. Its emulation type says
// whether the firmware should pretend the image is a floppy, a hard disk, or
// nothing at all - "no emulation", which is what every modern install disc
// uses, loading sectorCount sectors at loadSegment and jumping to them.

enum ElToritoPlatform : u8 {
    X86     = 0
    PowerPc = 1
    Mac     = 2
    Efi     = 0xEF
}

enum ElToritoBootMedia : u8 {
    NoEmulation  = 0
    Floppy12M    = 1
    Floppy144M   = 2
    Floppy288M   = 3
    HardDisk     = 4
}

// The first 32 bytes of the boot catalog: it validates the rest.
struct ElToritoValidationEntry {
    headerId   u8               "1"
    platformId ElToritoPlatform "firmware the entries that follow are for"
    reserved   u16              "zero"
    manufacturer char[24]       "who made the disc"
    checksum   u16              "makes the 16-bit words of this entry sum to zero"
    keyByte1   u8               "0x55"
    keyByte2   u8               "0xAA"
}

// The default boot entry, immediately after the validation entry.
struct ElToritoInitialEntry {
    bootIndicator u8                "0x88 bootable, 0x00 not bootable"
    bootMedia     ElToritoBootMedia "what the firmware should emulate"
    loadSegment   u16               "real-mode segment to load at; 0 means 0x7C0"
    systemType    u8                "partition type byte, copied from the image"
    unused        u8                "zero"
    sectorCount   u16               "virtual 512-byte sectors to load"
    loadRba       u32               "first sector of the boot image, in 2048-byte sectors"
    unused2       bytes[20]         "zero"
}

struct ElToritoBootCatalog {
    validation ElToritoValidationEntry "validation entry"
    initial    ElToritoInitialEntry    "the default boot entry"
}

struct ElTorito {
    skipToSector17 bytes[34816] "sectors 0-16: the system area and the primary volume descriptor"
    type       u8       "0 for a boot record volume descriptor"
    identifier char[5]  "CD001"
    version    u8       "1"
    systemId   char[32] "EL TORITO SPECIFICATION"
    unused     bytes[32] "zero"
    catalogSector u32   "sector holding the boot catalog"
    unused2    bytes[1973] "zero, to the end of the sector"
    catalogOffset = catalogSector * 2048
    // The boot catalog, followed to its sector. Placed by pointer; 2048 is the
    // sector size ISO 9660 discs always use.
    catalog at catalogOffset ElToritoBootCatalog "what to boot, and how"
}

// Java .class — big-endian. Magic, version, then the constant pool (a classic
// tag-dispatched table), access flags, this/super class and interfaces.
// Caveat: Long/Double constants (tags 5/6) each take TWO pool slots; this
// schema counts one slot per entry, so classes using those will desync after
// them (needs conditional counts to fix).
bitfield ClassAccess : u16 {
    public     0
    final      4
    super      5
    interface  9
    abstract   10
    synthetic  12
    annotation 13
    isEnum     14
    module     15
}

struct CpUtf8    { length u16  text string[length] "UTF-8 constant" }
struct CpRef     { classIndex u16  nameTypeIndex u16 "class/field/method reference" }
struct CpIndex1  { index u16 "single constant-pool index" }
struct CpMethodHandle { refKind u8  refIndex u16 "method handle" }

struct CpInfo {
    tag u8 "constant type tag"
    info match tag {
        1  => CpUtf8
        3  => u32
        4  => f32
        5  => u64
        6  => f64
        7  => CpIndex1
        8  => CpIndex1
        9  => CpRef
        10 => CpRef
        11 => CpRef
        12 => CpRef
        15 => CpMethodHandle
        16 => CpIndex1
        17 => CpRef
        18 => CpRef
        19 => CpIndex1
        20 => CpIndex1
    }
}

struct ClassFile {
    magic          char[4]     "magic CAFEBABE"
    minor          u16         "minor version"
    major          u16         "major version (52 = Java 8, 61 = Java 17)"
    cpCount        u16         "constant pool count (entries = count - 1)"
    cpEntries      = cpCount - 1
    constantPool   CpInfo[cpEntries] "the constant pool"
    accessFlags    ClassAccess "class access flags"
    thisClass      u16         "this class (constant-pool index)"
    superClass     u16         "super class (constant-pool index)"
    interfaceCount u16         "number of direct superinterfaces"
    interfaces     u16[interfaceCount] "interface constant-pool indices"
}

struct JpegSegment {
    marker  u16 "marker: 0xFFE0 APP0/JFIF, 0xFFE1 APP1/Exif, etc."
    length  u16 "segment length, including these two length bytes"
    dataLen = length - 2
    data    bytes[dataLen] "segment payload"
}

struct Jpeg {
    soi     u16 "0xFFD8 start-of-image marker"
    segment JpegSegment "the first marker segment after SOI"
}

// JPEG XL in its container form - the same box structure as MP4 and HEIF: a
// 32-bit size, a four-character type, then the body. A size of 1 means a 64-bit
// size follows; 0 means the box runs to the end of the file.
//
// A bare JPEG XL codestream instead starts with the two bytes FF 0A and is a
// bit-packed stream from its first byte, so it has no byte-aligned structure to
// walk; this pack covers the container, which is what a .jxl file from an
// encoder normally is. The container is required once a file carries Exif, XMP,
// an ICC profile, animation, or a reconstructible original JPEG.
//
// The boxes that matter:
//   JXL   the 12-byte signature box, always first
//   ftyp  file type, brand jxl
//   jxll  level: 5 for the baseline, 10 for images beyond its size limits
//   jxlc  the whole codestream, when it is stored in one piece
//   jxlp  one partial codestream, for progressive files; carries an index
//   jbrd  JPEG bitstream reconstruction data, to rebuild a source JPEG exactly
//   brob  a Brotli-compressed box, whose real type is its first four bytes
//   Exif  Exif metadata
//   xml   XMP metadata

struct JxlFileType {
    brand        char[4] "jxl "
    minorVersion u32     "minor version of the brand"
    // compatible brands, 4 chars each, run to the end of the box
}

struct JxlLevel {
    level u8 "codestream level: 5 baseline, 10 for very large or high bit depth images"
}

struct JxlPartialCodestream {
    index u32 "sequence number of this partial codestream; the high bit marks the last one"
}

struct JxlBrotliBox {
    innerType char[4] "the box type this expands to once Brotli-decompressed"
}

struct JxlBox {
    size  u32       "box size including this header; 1 = 64-bit size follows, 0 = to end of file"
    type  char[4]   "four-character box type"
    large u64       if size == 1 "64-bit box size, when size is 1"
    toEnd bytes[*]  if size == 0 "box body, running to the end of the file"
    bodyLen = size - 8
    body  bytes[bodyLen] if size > 7 "box body"
    // Typed view of the body, placed by pointer so the size walk is untouched.
    decoded at +8 match type {
        "ftyp" => JxlFileType
        "jxll" => JxlLevel
        "jxlp" => JxlPartialCodestream
        "brob" => JxlBrotliBox
        default => bytes[0]
    }
}

struct Jxl {
    boxes repeat JxlBox "top-level boxes, in file order, signature box first"
}

// LAS - the ASPRS exchange format for lidar, and what a laser scanner or an
// aerial survey delivers. A file is this public header block, then a run of
// variable length records carrying coordinate system and metadata, then the
// point records themselves at offsetToPointData.
//
// Coordinates are stored as 32-bit integers, not floats, which is the central
// design decision: a real coordinate is x * xScaleFactor + xOffset. That keeps
// a billion points compact and their precision uniform across the survey, at
// the cost of every reader having to apply the scaling. A scale of 0.01 with an
// offset near the survey origin is typical, giving centimetre resolution.
//
// pointDataRecordFormat says what each point carries. Formats 0 to 5 are the
// original records; 6 to 10, added in 1.4, widen the return numbers and
// classification and always carry GPS time:
//   0  x, y, z, intensity, return info, classification
//   1  format 0 plus GPS time
//   2  format 0 plus red, green, blue
//   3  format 1 plus colour
//   4  format 1 plus a waveform packet reference
//   5  format 3 plus a waveform packet reference
//   6  the 1.4 base record: wider fields, GPS time always present
//   7  format 6 plus colour        8  format 7 plus near infrared
//   9  format 6 plus waveform      10 format 7 plus waveform and infrared
//
// Version 1.4 also moved the point count. The two legacy fields below are kept
// for old readers and must be zero when a 1.4 file uses the wide point formats;
// the real counts are the 64-bit ones at the end.

bitfield LasGlobalEncoding : u16 {
    gpsTimeIsAdjustedStandard 0 // GPS time is adjusted standard time, not week time
    waveformDataInternal      1 // waveform packets are in this file
    waveformDataExternal      2 // waveform packets are in a .wdp file alongside
    syntheticReturnNumbers    3 // return numbers were generated, not measured
    wkt                       4 // the coordinate system is given as WKT, not GeoTIFF keys
}

struct Las {
    fileSignature      char[4]           "LASF"
    fileSourceId       u16               "flight line number, or 0 when unknown"
    globalEncoding     LasGlobalEncoding "how to read the GPS time and waveform fields"
    projectIdData1     u32               "project GUID, first component"
    projectIdData2     u16               "project GUID, second component"
    projectIdData3     u16               "project GUID, third component"
    projectIdData4     bytes[8]          "project GUID, last eight bytes"
    versionMajor       u8                "1"
    versionMinor       u8                "0 through 4"
    systemIdentifier   string[32]        "the hardware or process that produced the file"
    generatingSoftware string[32]        "the software that wrote it"
    creationDayOfYear  u16               "day of year the file was created, 1 to 366"
    creationYear       u16               "year the file was created"
    headerSize         u16               "bytes of header: 227 for 1.2, 235 for 1.3, 375 for 1.4"
    offsetToPointData  u32               "file offset of the first point record"
    numberOfVlrs       u32               "variable length records between this header and the points"
    pointDataFormat    u8                "which point record layout is used; see the list above"
    pointDataLength    u16               "bytes per point record, including any extra bytes"
    legacyPointCount   u32               "point count for readers older than 1.4; 0 in a 1.4 file using formats 6 to 10"
    legacyPointsByReturn u32[5]          "legacy per-return counts"
    xScaleFactor       f64               "multiply the stored x by this"
    yScaleFactor       f64               "multiply the stored y by this"
    zScaleFactor       f64               "multiply the stored z by this"
    xOffset            f64               "then add this to get real x"
    yOffset            f64               "then add this to get real y"
    zOffset            f64               "then add this to get real z"
    maxX               f64               "bounding box, in real coordinates"
    minX               f64
    maxY               f64
    minY               f64
    maxZ               f64
    minZ               f64
    startOfWaveformData u64 if versionMinor >= 3 "offset of the waveform data packet record, 1.3 and later"
    startOfFirstEvlr   u64 if versionMinor >= 4 "offset of the first extended variable length record"
    numberOfEvlrs      u32 if versionMinor >= 4 "extended variable length records, which may follow the points"
    pointCount         u64 if versionMinor >= 4 "the real point count in a 1.4 file"
    pointsByReturn     u64[15] if versionMinor >= 4 "points per return, up to fifteen returns"
}

// LZ4 frame format — magic, a frame descriptor, blocks, an end mark (a zero
// block size) and an optional content checksum. Each block is a 32-bit size
// whose top bit says the block is stored uncompressed, then the data, then an
// optional per-block checksum (frame flag). Because that flag lives in the
// descriptor, the walk comes in two flavours and the right one is chosen by it.

bitfield Lz4Flags : u8 {
    dictId            0    // a dictionary id follows the descriptor
    reserved          1
    contentChecksum   2    // an XXH32 of the whole content ends the frame
    contentSize       3    // an 8-byte uncompressed size follows
    blockChecksum     4    // every block is followed by an XXH32
    blockIndependence 5    // blocks do not depend on earlier blocks
    version           6..7 // frame version (1)
}

bitfield Lz4BlockDescriptor : u8 {
    blockMaxSize 4..6 // 4 = 64 KB, 5 = 256 KB, 6 = 1 MB, 7 = 4 MB
}

bitfield Lz4BlockSize : u32 {
    size         0..30 // block data size in bytes (0 = end mark)
    uncompressed 31    // block is stored, not compressed
}

struct Lz4Block {
    header  Lz4BlockSize "size and stored flag"
    dataLen = header.size
    data    bytes[dataLen] "block data (LZ4 sequences, or raw bytes if stored)"
}

struct Lz4CheckedBlock {
    header   Lz4BlockSize "size and stored flag"
    dataLen  = header.size
    data     bytes[dataLen] "block data (LZ4 sequences, or raw bytes if stored)"
    checksum u32 if dataLen > 0 "XXH32 of the block data"
}

struct Lz4Frame {
    magic           u32                "0x184D2204"
    flags           Lz4Flags           "frame descriptor flags"
    blockDescriptor Lz4BlockDescriptor "maximum block size"
    contentSize     u64 if flags.contentSize "uncompressed content size"
    dictId          u32 if flags.dictId      "dictionary id"
    headerChecksum  u8                 "second byte of XXH32 over the descriptor"
    blocks          repeat Lz4Block        until dataLen == 0 if flags.blockChecksum == 0 "blocks, ending with the end mark"
    checkedBlocks   repeat Lz4CheckedBlock until dataLen == 0 if flags.blockChecksum      "blocks with per-block checksums, ending with the end mark"
    contentChecksum u32 if flags.contentChecksum "XXH32 of the uncompressed content"
}

// Mach-O fat (universal) binary — a big-endian table of architecture slices,
// each pointing at a complete Mach-O image somewhere later in the file. Since
// the slices themselves are usually little-endian (x86_64, arm64), only their
// magic is peeked here; open a slice at its offset with the Mach-O pack.

enum CpuType : i32 {
    Vax       = 1
    Mc680x0   = 6
    X86       = 7
    X86_64    = 0x01000007
    Mc98000   = 10
    Hppa      = 11
    Arm       = 12
    Arm64     = 0x0100000C
    Arm64_32  = 0x0200000C
    Mc88000   = 13
    Sparc     = 14
    I860      = 15
    PowerPC   = 18
    PowerPC64 = 0x01000012
}

struct FatArch {
    cputype    CpuType "CPU family of this slice"
    cpusubtype u32     "CPU subtype (bit 31 = lib64; arm64e = 2, x86_64h = 8)"
    offset     u32     "file offset of the slice's Mach-O image"
    size       u32     "slice size in bytes"
    align      u32     "slice alignment as a power of two (14 = 16 KB)"
    sliceMagic at offset bytes[4] "Mach-O magic at the slice: CF FA ED FE = 64-bit LE, CE FA ED FE = 32-bit LE"
}

struct FatHeader {
    magic   u32              "0xCAFEBABE"
    nfatArch u32             "number of architecture slices"
    archs   FatArch[nfatArch] "one entry per slice"
}

// Mach-O fat (universal) binary — a big-endian table of architecture slices,
// each pointing at a complete Mach-O image somewhere later in the file. Since
// the slices themselves are usually little-endian (x86_64, arm64), only their
// magic is peeked here; open a slice at its offset with the Mach-O pack.

enum CpuType : i32 {
    Vax       = 1
    Mc680x0   = 6
    X86       = 7
    X86_64    = 0x01000007
    Mc98000   = 10
    Hppa      = 11
    Arm       = 12
    Arm64     = 0x0100000C
    Arm64_32  = 0x0200000C
    Mc88000   = 13
    Sparc     = 14
    I860      = 15
    PowerPC   = 18
    PowerPC64 = 0x01000012
}

struct FatArch {
    cputype    CpuType "CPU family of this slice"
    cpusubtype u32     "CPU subtype (bit 31 = lib64; arm64e = 2, x86_64h = 8)"
    offset     u32     "file offset of the slice's Mach-O image"
    size       u32     "slice size in bytes"
    align      u32     "slice alignment as a power of two (14 = 16 KB)"
    sliceMagic at offset bytes[4] "Mach-O magic at the slice: CF FA ED FE = 64-bit LE, CE FA ED FE = 32-bit LE"
}

struct FatHeader {
    magic   u32              "0xCAFEBABE"
    nfatArch u32             "number of architecture slices"
    archs   FatArch[nfatArch] "one entry per slice"
}

// Matroska - the open container behind .mkv, .mka and, restricted to VP8/VP9/
// AV1 with Vorbis/Opus, WebM. It is built on EBML, a binary XML: every
// element is an ID, a size, then data, and a master element's data is simply
// more elements. A file is an EBML header (DocType "matroska" or "webm")
// followed by one Segment holding everything else: SeekHead, Info, Tracks,
// then the Clusters of frames, then Cues (the seek index) and Tags.
//
// IDs and sizes are variable-length integers whose length is the count of
// leading zero bits in the first byte, plus one: 0x81 is a one-byte size of 1,
// 0x40 0x02 a two-byte size of 2, 0x01 followed by seven bytes an eight-byte
// one. The marker bit is stripped from sizes but kept in IDs, which is why IDs
// are written as 0x1A45DFA3 and not 0x0A45DFA3. A size of all ones means
// "unknown", which live streams use for the Segment and Clusters.
//
// Each element's type is looked up from its ID. A master element's children
// are listed only as far as the spec guarantees them, because a declarative
// walk cannot stop at the end of its parent; the Segment's children run to the
// end of the file, so every top-level element is walked.

// What an element is, picked by its ID, so the tree shows its name. Each reads
// no bytes: it only carries how to decode the element - kind 1 unsigned int,
// 2 string, 3 float, 4 date, 10 binary, 11 block, 20 master, 40 the Segment -
// and how many children a master is guaranteed. (A Cluster is not strictly
// guaranteed a block after its Timestamp, but in practice always has one.)
struct EbmlCrcFirst { present = 1 }
struct EbmlNoCrc    { present = 0 }

struct EBML {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 7 + crc.present
}
struct EBMLVersion         { kind = 1  children = 0 }
struct EBMLReadVersion     { kind = 1  children = 0 }
struct EBMLMaxIDLength     { kind = 1  children = 0 }
struct EBMLMaxSizeLength   { kind = 1  children = 0 }
struct DocType             { kind = 2  children = 0 }
struct DocTypeVersion      { kind = 1  children = 0 }
struct DocTypeReadVersion  { kind = 1  children = 0 }
struct Segment             { kind = 40 children = 0 }
struct SeekHead {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct Seek {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct SeekPosition        { kind = 1  children = 0 }
struct Info {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct TimestampScale      { kind = 1  children = 0 }
struct Duration            { kind = 3  children = 0 }
struct DateUTC             { kind = 4  children = 0 }
struct Title               { kind = 2  children = 0 }
struct MuxingApp           { kind = 2  children = 0 }
struct WritingApp          { kind = 2  children = 0 }
struct Tracks {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct TrackEntry {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 4 + crc.present
}
struct TrackNumber         { kind = 1  children = 0 }
struct TrackUID            { kind = 1  children = 0 }
struct TrackType           { kind = 1  children = 0 }
struct FlagEnabled         { kind = 1  children = 0 }
struct FlagDefault         { kind = 1  children = 0 }
struct FlagForced          { kind = 1  children = 0 }
struct FlagLacing          { kind = 1  children = 0 }
struct DefaultDuration     { kind = 1  children = 0 }
struct CodecDelay          { kind = 1  children = 0 }
struct SeekPreRoll         { kind = 1  children = 0 }
struct CodecID             { kind = 2  children = 0 }
struct CodecName           { kind = 2  children = 0 }
struct Name                { kind = 2  children = 0 }
struct Language            { kind = 2  children = 0 }
struct Video {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct PixelWidth          { kind = 1  children = 0 }
struct PixelHeight         { kind = 1  children = 0 }
struct DisplayWidth        { kind = 1  children = 0 }
struct DisplayHeight       { kind = 1  children = 0 }
struct FlagInterlaced      { kind = 1  children = 0 }
struct Audio {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct SamplingFrequency   { kind = 3  children = 0 }
struct Channels            { kind = 1  children = 0 }
struct BitDepth            { kind = 1  children = 0 }
struct Cluster {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct Timestamp           { kind = 1  children = 0 }
struct PrevSize            { kind = 1  children = 0 }
struct SimpleBlock         { kind = 11 children = 0 }
struct BlockGroup {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct Block               { kind = 11 children = 0 }
struct BlockDuration       { kind = 1  children = 0 }
struct Cues {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct CuePoint {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct CueTime             { kind = 1  children = 0 }
struct CueTrackPositions {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct CueTrack            { kind = 1  children = 0 }
struct CueClusterPosition  { kind = 1  children = 0 }
struct CueRelativePosition { kind = 1  children = 0 }
struct Tags {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct Tag {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct SimpleTag {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 2 + crc.present
}
struct TagName             { kind = 2  children = 0 }
struct TagString           { kind = 2  children = 0 }
struct Chapters {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct Attachments {
    kind     = 20
    first    at +0 u8
    crc      match first { 0xBF => EbmlCrcFirst default => EbmlNoCrc }
    children = 1 + crc.present
}
struct Void                { kind = 10 children = 0 } // padding, left for a later rewrite to grow into
struct CRC32               { kind = 10 children = 0 } // CRC-32 of the parent's other children, little-endian
struct SeekID              { kind = 10 children = 0 } // the ID of the element a Seek points at
struct SegmentUUID         { kind = 10 children = 0 }
struct CodecPrivate        { kind = 10 children = 0 } // codec setup data, e.g. the OpusHead or avcC record
struct Targets             { kind = 10 children = 0 } // what a Tag applies to; often empty, so shown raw
struct Binary              { kind = 10 children = 0 } // any element not named here

// A one-byte ID: the first byte has its top bit set.
struct EbmlIdShort {
    value  u8 "the ID"
    length = 1
}

// A two- to four-byte ID. The width is read off the first byte's high nibble
// (0x4-0x7 two bytes, 0x2-0x3 three, 0x1 four) and the ID is the top bytes of
// a 32-bit peek.
struct EbmlIdLong {
    peek   at +0 u32
    first  at +0 u8
    nibble = first / 16
    two    = (nibble / 4 + 3) / 4
    three  = (nibble / 2 + 7) / 8 - two
    four   = 1 - two - three
    length = 2 * two + 3 * three + 4 * four
    value  = two * (peek / 65536) + three * (peek / 256) + four * peek
    raw    bytes[length]
}

struct EbmlId {
    first   at +0 u8
    short   = first / 128
    coded match short {
        1 => EbmlIdShort
        0 => EbmlIdLong
    }
    value  = coded.value
    length = coded.length
}

// A one-byte size: the marker bit, then seven bits of value. 0xFF is unknown.
struct EbmlVintShort {
    byte    u8
    length  = 1
    value   = byte - 128
    unknown = (value + 1) / 128
}

// A two- to eight-byte size, taken from a 64-bit peek. Each atLeastN is 1 when
// the first byte is 2^(8-N) or more, so exactly one widthN (their difference)
// is 1, and it selects the shift and marker to strip.
struct EbmlVintLong {
    peek     at +0 i64
    first    at +0 u8
    atLeast2 = (first / 64 + 3) / 4
    atLeast3 = (first / 32 + 7) / 8
    atLeast4 = (first / 16 + 15) / 16
    atLeast5 = (first / 8 + 31) / 32
    atLeast6 = (first / 4 + 63) / 64
    atLeast7 = (first / 2 + 127) / 128
    atLeast8 = (first + 255) / 256
    width2   = atLeast2
    width3   = atLeast3 - atLeast2
    width4   = atLeast4 - atLeast3
    width5   = atLeast5 - atLeast4
    width6   = atLeast6 - atLeast5
    width7   = atLeast7 - atLeast6
    width8   = atLeast8 - atLeast7
    length   = 2 * width2 + 3 * width3 + 4 * width4 + 5 * width5 + 6 * width6 + 7 * width7 + 8 * width8
    value    = width2 * (peek / 281474976710656 - 16384) + width3 * (peek / 1099511627776 - 2097152) + width4 * (peek / 4294967296 - 268435456) + width5 * (peek / 16777216 - 34359738368) + width6 * (peek / 65536 - 4398046511104) + width7 * (peek / 256 - 562949953421312) + width8 * (peek - 72057594037927936)
    limit    = width2 * 16384 + width3 * 2097152 + width4 * 268435456 + width5 * 34359738368 + width6 * 4398046511104 + width7 * 562949953421312 + width8 * 72057594037927936
    unknown  = (value + 1) / limit
    raw      bytes[length]
}

struct EbmlVint {
    first  at +0 u8
    short  = first / 128
    coded match short {
        1 => EbmlVintShort
        0 => EbmlVintLong
    }
    value   = coded.value
    length  = coded.length
    unknown = coded.unknown
    known   = 1 - unknown
}

struct EbmlUint24 {
    high  u8
    low   u16
    value = high * 65536 + low
}

bitfield MkvBlockFlags : u8 {
    discardable 0    // may be dropped when decoding is too slow
    lacing      1..2 // 0 none, 1 Xiph, 2 fixed-size, 3 EBML: several frames in one block
    invisible   3    // decoded but not shown
    keyframe    7    // SimpleBlock only: decodable on its own
}

// The start of a SimpleBlock or Block; the frame data follows.
struct MkvBlockHeader {
    track    EbmlVint      "track number"
    timecode i16           "time relative to the cluster's Timestamp, in TimestampScale units"
    flags    MkvBlockFlags
}

struct EbmlElement {
    id       EbmlId   "element ID"
    size     EbmlVint "size of the element's data"
    dataSize = size.value
    headerLength = id.length + size.length
    element match id.value {
        0x1A45DFA3 => EBML
        0x4286     => EBMLVersion
        0x42F7     => EBMLReadVersion
        0x42F2     => EBMLMaxIDLength
        0x42F3     => EBMLMaxSizeLength
        0x4282     => DocType
        0x4287     => DocTypeVersion
        0x4285     => DocTypeReadVersion
        0x18538067 => Segment
        0x114D9B74 => SeekHead
        0x4DBB     => Seek
        0x53AC     => SeekPosition
        0x1549A966 => Info
        0x2AD7B1   => TimestampScale
        0x4489     => Duration
        0x4461     => DateUTC
        0x7BA9     => Title
        0x4D80     => MuxingApp
        0x5741     => WritingApp
        0x1654AE6B => Tracks
        0xAE       => TrackEntry
        0xD7       => TrackNumber
        0x73C5     => TrackUID
        0x83       => TrackType
        0xB9       => FlagEnabled
        0x88       => FlagDefault
        0x55AA     => FlagForced
        0x9C       => FlagLacing
        0x23E383   => DefaultDuration
        0x56AA     => CodecDelay
        0x56BB     => SeekPreRoll
        0x86       => CodecID
        0x258688   => CodecName
        0x536E     => Name
        0x22B59C   => Language
        0xE0       => Video
        0xB0       => PixelWidth
        0xBA       => PixelHeight
        0x54B0     => DisplayWidth
        0x54BA     => DisplayHeight
        0x9A       => FlagInterlaced
        0xE1       => Audio
        0xB5       => SamplingFrequency
        0x9F       => Channels
        0x6264     => BitDepth
        0x1F43B675 => Cluster
        0xE7       => Timestamp
        0xAB       => PrevSize
        0xA3       => SimpleBlock
        0xA0       => BlockGroup
        0xA1       => Block
        0x9B       => BlockDuration
        0x1C53BB6B => Cues
        0xBB       => CuePoint
        0xB3       => CueTime
        0xB7       => CueTrackPositions
        0xF7       => CueTrack
        0xF1       => CueClusterPosition
        0xF0       => CueRelativePosition
        0x1254C367 => Tags
        0x7373     => Tag
        0x67C8     => SimpleTag
        0x45A3     => TagName
        0x4487     => TagString
        0x1043A770 => Chapters
        0x1941A469 => Attachments
        0xEC       => Void
        0xBF       => CRC32
        0x53AB     => SeekID
        0x73A4     => SegmentUUID
        0x63A2     => CodecPrivate
        0x63C0     => Targets
        default    => Binary
    }
    kind       = element.kind
    childCount = element.children
    uint  match dataSize {
        1 => u8
        2 => u16
        3 => EbmlUint24
        4 => u32
        8 => u64
        default => bytes[dataSize]
    } if kind == 1
    text  string[dataSize] if kind == 2
    float match dataSize {
        4 => f32
        8 => f64
        default => bytes[dataSize]
    } if kind == 3
    date  i64 if kind == 4 "nanoseconds since 2001-01-01 UTC"
    rawLength = dataSize * size.known
    data  bytes[rawLength] if kind >= 10 "element data"
    rest  bytes[*] if size.unknown "unknown size: the data runs on to the end of its parent"
    block at +headerLength MkvBlockHeader if kind == 11 "block header; frame data follows"
    children at +headerLength EbmlElement[childCount] if childCount "the children the spec guarantees"
    segment  at +headerLength repeat EbmlElement if kind == 40 "the segment's top-level elements"
}

struct Matroska {
    elements repeat EbmlElement "the EBML header, then the Segment"
}

// Standard MIDI File - big-endian, and built from chunks: a four-character
// type, a 32-bit length, then that many bytes. The first chunk is always MThd
// and always six bytes long; every chunk after it is an MTrk holding one
// track's event stream.
//
// Events inside a track are delta-time / message pairs where the delta time is
// a variable-length quantity, so a declarative walk cannot step through them.
// Each MTrk is therefore shown as its length and its bytes, which is enough to
// see how the tracks are laid out and where each one ends.
//
// division is the one field whose meaning changes with its sign. Positive is
// metrical time: ticks per quarter note (96, 480 and 960 are the common
// values). Negative is SMPTE time: the high byte is the negated frame rate
// (24, 25, 29 for drop-frame, 30) and the low byte the ticks per frame.

enum MidiFormat : u16 {
    SingleTrack        = 0 // one track holding everything
    SimultaneousTracks = 1 // tracks played together, one song
    IndependentTracks  = 2 // tracks are separate songs or patterns
}

struct MidiHeader {
    type     char[4]    "MThd"
    length   u32        "bytes of header data; always 6"
    format   MidiFormat "how the tracks relate to each other"
    ntrks    u16        "number of track chunks (always 1 for format 0)"
    division i16        "ticks per quarter note, or SMPTE when negative"
}

struct MidiTrack {
    type   char[4]       "MTrk"
    length u32           "bytes of event data in this track"
    events bytes[length] "delta time / message pairs, ending with the end-of-track meta event FF 2F 00"
}

struct Midi {
    header MidiHeader       "the MThd chunk: format, track count, time division"
    tracks repeat MidiTrack "one MTrk per track, in order"
}

// ID3v2 — the metadata tag that starts almost every MP3 file. The tag is a
// 10-byte header followed by frames; the MPEG audio frames begin right after
// the tag (at 10 + size). Sizes in the header are "syncsafe": four 7-bit
// bytes, so no byte ever looks like an MPEG sync (0xFF).
//
// The frame layout changed between versions, so the walk picks the frame type
// by the version byte: v2.2 uses 3-byte ids and sizes, v2.3 a plain 32-bit
// size, v2.4 a syncsafe size. Common text frames get their text decoded; the
// walk stops at the first zeroed id (the padding after the last frame).

bitfield Id3Flags : u8 {
    footer            4 // a 10-byte footer copies the header at the tag's end (v2.4)
    experimental      5 // tag is in an experimental stage
    extendedHeader    6 // an extended header follows this one
    unsynchronisation 7 // unsynchronisation applied to the whole tag
}

// A 28-bit syncsafe integer: four bytes, 7 bits each, big-endian.
struct Id3Syncsafe {
    b0 u8
    b1 u8
    b2 u8
    b3 u8
    value = b0 * 2097152 + b1 * 16384 + b2 * 128 + b3
}

enum Id3Encoding : u8 {
    Latin1  = 0
    Utf16   = 1
    Utf16BE = 2
    Utf8    = 3
}

bitfield Id3FrameFlags : u16 {
    dataLengthIndicator 0  // v2.4: a syncsafe data length precedes the body
    unsynchronised      1  // v2.4: frame body is unsynchronised
    encrypted           2  // v2.4 (bit 6 in v2.3)
    compressed          3  // v2.4 (bit 7 in v2.3)
    groupingIdentity    6  // v2.4 (bit 5 in v2.3)
    readOnly            12
    fileAlterPreserve   13
    tagAlterPreserve    14
}

// v2.3: 4-char id, plain big-endian size, 16-bit flags.
struct Id3v23Frame {
    id       string[4]      "frame id (TIT2 title, TPE1 artist, TALB album, APIC picture, ...)"
    size     u32            "body size, excluding this 10-byte header"
    flags    Id3FrameFlags  "frame status and format flags"
    body     bytes[size]    "frame body"
    textLen  = size - 1
    // Text frames: an encoding byte then the text. Decoded by pointer so the
    // frame walk above is unaffected for non-text frames.
    encoding at +10 match id {
        "TIT2" => Id3Encoding  "TPE1" => Id3Encoding  "TALB" => Id3Encoding
        "TYER" => Id3Encoding  "TRCK" => Id3Encoding  "TCON" => Id3Encoding
        "TPE2" => Id3Encoding  "TCOM" => Id3Encoding  "TPOS" => Id3Encoding
        "TPUB" => Id3Encoding  "TSSE" => Id3Encoding  "TXXX" => Id3Encoding
        "TENC" => Id3Encoding  "TCOP" => Id3Encoding  "TDRC" => Id3Encoding
        default => bytes[0]
    }
    text at +11 match id {
        "TIT2" => string[textLen]  "TPE1" => string[textLen]  "TALB" => string[textLen]
        "TYER" => string[textLen]  "TRCK" => string[textLen]  "TCON" => string[textLen]
        "TPE2" => string[textLen]  "TCOM" => string[textLen]  "TPOS" => string[textLen]
        "TPUB" => string[textLen]  "TSSE" => string[textLen]  "TXXX" => string[textLen]
        "TENC" => string[textLen]  "TCOP" => string[textLen]  "TDRC" => string[textLen]
        default => bytes[0]
    }
}

// v2.4: same shape as v2.3 but the size is syncsafe.
struct Id3v24Frame {
    id       string[4]      "frame id (TIT2 title, TPE1 artist, TALB album, TDRC date, APIC picture, ...)"
    sizeRaw  Id3Syncsafe    "syncsafe body size"
    size     = sizeRaw.value
    flags    Id3FrameFlags  "frame status and format flags"
    body     bytes[size]    "frame body"
    textLen  = size - 1
    encoding at +10 match id {
        "TIT2" => Id3Encoding  "TPE1" => Id3Encoding  "TALB" => Id3Encoding
        "TDRC" => Id3Encoding  "TRCK" => Id3Encoding  "TCON" => Id3Encoding
        "TPE2" => Id3Encoding  "TCOM" => Id3Encoding  "TPOS" => Id3Encoding
        "TPUB" => Id3Encoding  "TSSE" => Id3Encoding  "TXXX" => Id3Encoding
        "TENC" => Id3Encoding  "TCOP" => Id3Encoding  "TYER" => Id3Encoding
        default => bytes[0]
    }
    text at +11 match id {
        "TIT2" => string[textLen]  "TPE1" => string[textLen]  "TALB" => string[textLen]
        "TDRC" => string[textLen]  "TRCK" => string[textLen]  "TCON" => string[textLen]
        "TPE2" => string[textLen]  "TCOM" => string[textLen]  "TPOS" => string[textLen]
        "TPUB" => string[textLen]  "TSSE" => string[textLen]  "TXXX" => string[textLen]
        "TENC" => string[textLen]  "TCOP" => string[textLen]  "TYER" => string[textLen]
        default => bytes[0]
    }
}

// v2.2: 3-char id and a 24-bit size, no flags.
struct Id3v22Frame {
    id      string[3] "frame id (TT2 title, TP1 artist, TAL album, PIC picture, ...)"
    s0      u8
    s1      u8
    s2      u8
    size    = s0 * 65536 + s1 * 256 + s2
    body    bytes[size] "frame body"
    textLen = size - 1
    encoding at +6 match id {
        "TT2" => Id3Encoding  "TP1" => Id3Encoding  "TAL" => Id3Encoding
        "TYE" => Id3Encoding  "TRK" => Id3Encoding  "TCO" => Id3Encoding
        default => bytes[0]
    }
    text at +7 match id {
        "TT2" => string[textLen]  "TP1" => string[textLen]  "TAL" => string[textLen]
        "TYE" => string[textLen]  "TRK" => string[textLen]  "TCO" => string[textLen]
        default => bytes[0]
    }
}

struct Id3v2 {
    magic        string[3]   "always ID3"
    versionMajor u8          "ID3v2 version: 2, 3 or 4"
    revision     u8          "revision (0)"
    flags        Id3Flags    "tag-level flags"
    sizeRaw      Id3Syncsafe "syncsafe tag size, excluding this header"
    tagSize      = sizeRaw.value
    audioOffset  = tagSize + 10
    // Extended header (rare). v2.3 semantics: the size excludes its own 4 bytes.
    extendedSize u32                 if flags.extendedHeader
    extended     bytes[extendedSize] if flags.extendedHeader
    // One frame walk per version. Each stops at the padding (a zeroed id);
    // a tag with no padding ends when the audio frames fail to parse as a frame.
    frames22 repeat Id3v22Frame until id == "" if versionMajor == 2
    frames23 repeat Id3v23Frame until id == "" if versionMajor == 3
    frames24 repeat Id3v24Frame until id == "" if versionMajor == 4
    // The first MPEG audio frame starts right after the tag: sync 0xFFE0+.
    audioSync at audioOffset bytes[4] "first bytes after the tag: the first MPEG frame header (FF Fx / FF Ex)"
}

// ISO base media file format (ISO/IEC 14496-12) — the box structure shared by
// MP4, QuickTime MOV, M4A, 3GP and the HEIF family. A file is a sequence of
// boxes: 32-bit size, 4-char type, then the body. A size of 1 means a 64-bit
// size follows (large mdat); 0 means "to end of file".
//
// This pack walks the top-level boxes by size and decodes the headers that
// carry the metadata: ftyp, and inside moov the mvhd (duration, timescale),
// plus tkhd / mdhd / hdlr by descending into the first two children of each
// container. A declarative walk cannot be told where a container ends, so
// containers show only the children that are guaranteed to be there.

struct Ftyp {
    majorBrand   string[4] "brand best describing the file (isom, mp42, qt  , M4A , heic, avif)"
    minorVersion u32       "minor version of the major brand"
    // compatible brands (4 chars each) follow to the end of the box
}

// Movie header (a FullBox: version + 24-bit flags, then the fields).
struct Mvhd {
    version          u8       "0 = 32-bit times, 1 = 64-bit times"
    flags            bytes[3]
    creationTime     u32      if version == 0 "seconds since 1904-01-01 UTC"
    modificationTime u32      if version == 0 "seconds since 1904-01-01 UTC"
    timescale        u32      if version == 0 "time units per second"
    duration         u32      if version == 0 "presentation length in timescale units"
    creationTime64     u64    if version == 1 "seconds since 1904-01-01 UTC"
    modificationTime64 u64    if version == 1 "seconds since 1904-01-01 UTC"
    timescale64        u32    if version == 1 "time units per second"
    duration64         u64    if version == 1 "presentation length in timescale units"
    rate             i32      "preferred playback rate, 16.16 fixed point (0x00010000 = 1.0)"
    volume           i16      "preferred volume, 8.8 fixed point (0x0100 = full)"
    reserved         bytes[10]
    matrix           i32[9]   "video transformation matrix"
    preDefined       bytes[24]
    nextTrackId      u32      "next available track id"
}

// Track header.
struct Tkhd {
    version          u8       "0 = 32-bit times, 1 = 64-bit times"
    flags            bytes[3] "0x000001 enabled, 0x000002 in movie, 0x000004 in preview"
    creationTime     u32      if version == 0 "seconds since 1904-01-01 UTC"
    modificationTime u32      if version == 0 "seconds since 1904-01-01 UTC"
    trackId          u32      if version == 0 "track id (never 0)"
    reserved0        u32      if version == 0
    duration         u32      if version == 0 "track length in movie timescale units"
    creationTime64     u64    if version == 1 "seconds since 1904-01-01 UTC"
    modificationTime64 u64    if version == 1 "seconds since 1904-01-01 UTC"
    trackId64          u32    if version == 1 "track id (never 0)"
    reserved064        u32    if version == 1
    duration64         u64    if version == 1 "track length in movie timescale units"
    reserved1        u32[2]
    layer            i16      "front-to-back ordering (0 = normal)"
    alternateGroup   i16      "alternate track group (0 = none)"
    volume           i16      "8.8 fixed point; 0x0100 for audio, 0 for video"
    reserved2        u16
    matrix           i32[9]   "video transformation matrix"
    width            u32      "visual presentation width, 16.16 fixed point"
    height           u32      "visual presentation height, 16.16 fixed point"
}

// Media header.
struct Mdhd {
    version          u8       "0 = 32-bit times, 1 = 64-bit times"
    flags            bytes[3]
    creationTime     u32      if version == 0 "seconds since 1904-01-01 UTC"
    modificationTime u32      if version == 0 "seconds since 1904-01-01 UTC"
    timescale        u32      if version == 0 "time units per second for this media"
    duration         u32      if version == 0 "media length in its timescale"
    creationTime64     u64    if version == 1 "seconds since 1904-01-01 UTC"
    modificationTime64 u64    if version == 1 "seconds since 1904-01-01 UTC"
    timescale64        u32    if version == 1 "time units per second for this media"
    duration64         u64    if version == 1 "media length in its timescale"
    language         u16      "ISO 639-2 code, three 5-bit letters (0x55C4 = und)"
    preDefined       u16
}

// Handler reference: what kind of media a track carries.
struct Hdlr {
    version     u8
    flags       bytes[3]
    preDefined  u32
    handlerType string[4] "vide video, soun audio, hint, meta, text, subt subtitles"
    reserved    u32[3]
    name        cstring   "human-readable handler name"
}

// A box whose 32-bit size is 1: the real size is the 64-bit field that follows.
struct LargeBox {
    largesize u64 "64-bit box size, header included"
    bodyLen   = largesize - 16
    body      bytes[bodyLen] "box body"
}

// A pure container: only the first child is decoded (see the note at the top).
struct Container {
    first Box "first child box"
}

// A container that always has at least two children (moov, trak, mdia, minf):
// the second child is found by stepping over the first.
struct Container2 {
    first     Box "first child box"
    secondPos = first.size
    second    at +secondPos Box "second child box"
}

// A FullBox container (meta): version and flags precede the children.
struct FullContainer {
    version u8
    flags   bytes[3]
    first   Box "first child box"
}

struct Box {
    size    u32       "box size including this header; 1 = 64-bit size follows, 0 = to end of file"
    type    string[4] "four-character box type"
    large   LargeBox  if size == 1
    toEnd   bytes[*]  if size == 0 "box body, running to the end of the file"
    bodyLen = size - 8
    body    bytes[bodyLen] if size > 7 "box body"
    // Typed view of the body, placed by pointer so the size walk is untouched.
    decoded at +8 match type {
        "ftyp" => Ftyp
        "mvhd" => Mvhd
        "tkhd" => Tkhd
        "mdhd" => Mdhd
        "hdlr" => Hdlr
        "moov" => Container2
        "trak" => Container2
        "mdia" => Container2
        "minf" => Container2
        "stbl" => Container
        "edts" => Container
        "dinf" => Container
        "udta" => Container
        "moof" => Container
        "traf" => Container
        "mvex" => Container
        "meta" => FullContainer
        default => bytes[0]
    }
}

struct IsoMedia {
    boxes repeat Box "top-level boxes, in file order"
}

// A PDB is the symbol file the Microsoft toolchain writes next to an executable,
// and like a compound file it is a small filesystem: the container is MSF, the
// Multi-Stream Format, and the debug information sits inside it as numbered
// streams. A debugger opens the PDB, finds stream 1 to check the GUID matches
// the binary, then reads the streams it needs.
//
// The file is an array of fixed-size blocks, 4096 bytes by default, numbered
// from 0 - this superblock is block 0. A stream is a list of block numbers, and
// the stream directory is itself a stream, which creates a bootstrapping
// problem: the directory can be longer than one block, so its block list may not
// fit in one block either. MSF solves it with an indirection. blockMapAddr
// points at a block holding the block numbers of the directory, and
// numDirectoryBytes says how long the directory is.
//
// freeBlockMapBlock is either 1 or 2, and the other one is a spare. A writer
// builds the new allocation bitmap in the unused slot and then flips this field,
// so a PDB is never left with a half-written free list - the same trick a
// journalling filesystem uses, done with two blocks.
//
// The streams that matter, once the directory is read: stream 1 is the PDB
// information stream, with the GUID and age that must match the executable's
// debug directory; stream 2 the TPI (type information); stream 3 the DBI (module
// and section contributions); stream 4 the IPI. The rest are per-module symbol
// streams.
//
// The much older MSF 2.0 container starts with Microsoft C/C++ program database
// 2.00 instead, and is not matched here.

struct MsfSuperBlock {
    magic             bytes[32] "Microsoft C/C++ MSF 7.00, CR LF, 1A, DS, then three zero bytes"
    blockSize         u32       "bytes per block: 512, 1024, 2048 or 4096"
    freeBlockMapBlock u32       "which of blocks 1 and 2 holds the live allocation bitmap"
    numBlocks         u32       "blocks in the file; blockSize times this is the file length"
    numDirectoryBytes u32       "length of the stream directory in bytes"
    unknown           u32       "unused, zero"
    blockMapAddr      u32       "block holding the list of blocks that make up the stream directory"
}

// The Nintendo 64 cartridge header - 64 bytes, big-endian, and followed by the
// 4032-byte IPL3 boot code that the console runs before the game.
//
// The first word doubles as a byte-order mark, which is why N64 ROM dumps come
// in three flavours. 80 37 12 40 is the native big-endian order, the .z64
// files this pack matches. A dump in 16-bit byte-swapped order (.v64) starts
// 37 80 40 12, and a little-endian one (.n64) starts 40 12 37 80 - both need
// reordering before anything below lines up.
//
// crc1 and crc2 are the checksums the CIC lockout chip and IPL3 verify over the
// first megabyte of the ROM. They are not a plain CRC-32: the algorithm depends
// on which CIC variant the cartridge carries, and a ROM patcher has to
// recompute them or the console refuses to boot.
//
// The cartridge id is what a ROM database identifies a game by - NSME is Super
// Mario 64, North America - and the country code says which region the
// cartridge was sold in: 45 E North America, 4A J Japan, 50 P Europe.

struct N64Rom {
    endianness   bytes[4]  "80 37 12 40 in a native big-endian dump"
    clockRate    u32       "clock rate override for the PI bus; 0 means use the default"
    bootAddress  u32       "virtual address IPL3 loads the game to, usually 0x80000400"
    libultraVersion u32    "release and revision of the libultra SDK the game was built with"
    crc1         u32       "first CIC check code over the first megabyte"
    crc2         u32       "second CIC check code"
    unused1      bytes[8]  "unused, zero"
    imageName    string[20] "internal game title, uppercase ASCII, space padded"
    unused2      bytes[7]  "unused, zero"
    mediaFormat  char      "N for a cartridge, D for 64DD disk, C for a cartridge part of a disk pair"
    cartridgeId  string[2] "two-character game id, as a ROM database lists it"
    countryCode  char      "region the cartridge was sold in: E, J or P"
    version      u8        "revision of the game, counting from 0"
    // The 4032 bytes that follow are IPL3, the boot code the PIF hands control
    // to; the game's own code starts after it.
}

// iNES - the header every NES emulator reads. A cartridge is not a program
// file; it is the contents of two ROM chips wired to the console, and the
// header exists only because a dump on its own cannot say how they were
// wired. PRG ROM is what the CPU sees, CHR ROM is what the picture unit sees,
// and the mapper number names the bank-switching hardware on the cartridge
// that made both bigger than the address space allowed.
//
// The mapper number is split across two nibbles in two different bytes, a
// consequence of the format growing one field at a time; it is recombined
// below. NES 2.0 extends the same header - flags7 bits 2-3 read as 2 - and
// reinterprets the later bytes, so those are left as raw flags here.
//
// A cartridge with no CHR ROM had CHR RAM instead, and chrRomSize is 0.

bitfield NesFlags6 : u8 {
    mirroring  0    // 0 = horizontal, 1 = vertical
    battery    1    // battery-backed save RAM at 0x6000
    trainer    2    // a 512-byte trainer precedes the PRG data
    fourScreen 3    // four-screen VRAM, ignoring the mirroring bit
    mapperLow  4..7 // low nibble of the mapper number
}

bitfield NesFlags7 : u8 {
    vsUnisystem 0    // arcade VS. System cartridge
    playChoice  1    // PlayChoice-10 cartridge, with 8 KB of extra data
    nes2        2..3 // 2 marks a NES 2.0 header
    mapperHigh  4..7 // high nibble of the mapper number
}

struct Nes {
    magic      bytes[4]   "4E 45 53 1A"
    prgRomSize u8         "PRG ROM in 16 KiB units: what the CPU executes"
    chrRomSize u8         "CHR ROM in 8 KiB units: tile data; 0 means CHR RAM"
    flags6     NesFlags6  "mirroring, battery, trainer, and the low mapper nibble"
    flags7     NesFlags7  "console type, NES 2.0 marker, and the high mapper nibble"
    mapper     = flags7.mapperHigh * 16 + flags6.mapperLow
    flags8     u8         "PRG RAM size in iNES; mapper bits 8-11 in NES 2.0"
    flags9     u8         "TV system in iNES; ROM size upper bits in NES 2.0"
    flags10    u8         "unofficial TV system and PRG RAM flags"
    padding    bytes[5]   "zero; a NES 2.0 header uses these"
    prgBytes   = prgRomSize * 16384
    chrBytes   = chrRomSize * 8192
    trainer    bytes[512] if flags6.trainer "512-byte trainer, mapped at 0x7000"
    prgRom     bytes[prgBytes] "program ROM, mapped at 0x8000"
    chrRom     bytes[chrBytes] "character ROM: the pattern tables"
}

// NTFS boot sector - the first sector of the volume. It looks like a FAT boot
// sector for the first eleven bytes, because it has to: the same BIOS loads
// both. After that the BPB is mostly zeros, since NTFS keeps almost nothing
// here. Everything the filesystem needs lives in the master file table, and
// the only job of this sector is to say which cluster that table starts at.
//
// The MFT is itself a file, described by its own first record, so the volume
// bootstraps from mftCluster. mftMirrorCluster points at a copy of the first
// few records, kept elsewhere on the volume so a damaged MFT can be recovered.
//
// Two fields use a sign trick: when clustersPerFileRecord is positive it is a
// count of clusters, and when it is negative the record size is 2 to the power
// of its absolute value in bytes. That is how a 1024-byte MFT record fits on a
// volume with 4096-byte clusters, which is the normal case - the value is
// typically -10.

struct Ntfs {
    jump                  bytes[3] "EB 52 90: a jump to the boot code"
    oemId                 char[8]  "NTFS followed by four spaces"
    bytesPerSector        u16      "512 on essentially everything"
    sectorsPerCluster     u8       "cluster size, a power of two"
    reservedSectors       u16      "0 on NTFS"
    unusedFats            bytes[3] "zero: where FAT keeps its table count"
    unusedRootEntries     u16      "zero"
    unusedTotalSectors    u16      "zero"
    mediaDescriptor       u8       "0xF8 for a fixed disk"
    unusedSectorsPerFat   u16      "zero"
    sectorsPerTrack       u16      "disk geometry, for the BIOS"
    numberOfHeads         u16      "disk geometry, for the BIOS"
    hiddenSectors         u32      "sectors before this partition on the disk"
    unusedTotalSectors32  u32      "zero"
    unusedDriveNumber     u32      "usually 0x00800080"
    totalSectors          u64      "sectors in the volume, one short of the partition"
    mftCluster            u64      "first cluster of the master file table"
    mftMirrorCluster      u64      "first cluster of the MFT mirror"
    clustersPerFileRecord i8       "positive: clusters per record; negative: 2^-n bytes"
    unused2               bytes[3] "zero"
    clustersPerIndexBuffer i8      "same encoding, for index allocation buffers"
    unused3               bytes[3] "zero"
    volumeSerialNumber    u64      "64-bit volume serial, set at format time"
    checksum              u32      "unused in practice, zero"
    bootCode              bytes[426] "the boot code the jump above lands in"
    endMarker             u16      "0xAA55, the sector signature"
}

// Ogg — Xiph.org's page-based container for Vorbis, Opus, FLAC, Theora and
// Speex. Every page starts with a 27-byte header followed by a segment table;
// the payload length is the sum of the segment table entries, which a
// declarative schema cannot add up, so this pack decodes the first page.
//
// That first page is the interesting one: it is the "beginning of stream" page
// and carries exactly one packet — the codec's identification header — which
// is decoded here by its first byte (the packet type).

bitfield OggHeaderType : u8 {
    continued 0 // first packet continues from the previous page
    bos       1 // beginning of stream: first page of a logical bitstream
    eos       2 // end of stream: last page of a logical bitstream
}

// Vorbis identification header (packet type 1, then "vorbis").
bitfield VorbisBlocksizes : u8 {
    blocksize0 0..3 // log2 of the short block size
    blocksize1 4..7 // log2 of the long block size
}

struct VorbisIdentification {
    packetType     u8               "1 = identification header"
    codec          string[6]        "always vorbis"
    version        u32              "Vorbis version (0)"
    channels       u8               "audio channels"
    sampleRate     u32              "sample rate (Hz)"
    bitrateMaximum i32              "maximum bitrate hint (0 = unset)"
    bitrateNominal i32              "nominal bitrate (0 = unset)"
    bitrateMinimum i32              "minimum bitrate hint (0 = unset)"
    blocksizes     VorbisBlocksizes "log2 short/long block sizes"
    framing        u8               "framing bit (must be 1)"
}

// Opus identification header ("OpusHead", RFC 7845).
struct OpusHead {
    magic            string[8] "always OpusHead"
    version          u8        "encapsulation version (1)"
    channels         u8        "output channel count"
    preSkip          u16       "samples to discard at 48 kHz"
    inputSampleRate  u32       "original input sample rate (Hz), informational"
    outputGain       i16       "output gain in Q7.8 dB"
    mappingFamily    u8        "channel mapping family (0 = mono/stereo)"
}

// Ogg FLAC identification (0x7F, "FLAC"). The version and packet count are
// followed by the native "fLaC" stream marker and a big-endian STREAMINFO.
struct OggFlacIdentification {
    packetType    u8        "0x7F"
    signature     string[4] "always FLAC"
    majorVersion  u8        "Ogg FLAC mapping major version (1)"
    minorVersion  u8        "Ogg FLAC mapping minor version (0)"
    headerPackets bytes[2]  "big-endian count of header packets that follow (0 = unknown)"
    nativeMarker  string[4] "fLaC: a native FLAC stream begins here"
}

// Theora identification header (0x80, "theora"). The remaining fields are
// big-endian and bit-packed, so only the version is decoded here.
struct TheoraIdentification {
    packetType   u8        "0x80 = identification header"
    codec        string[6] "always theora"
    versionMajor u8        "bitstream version major (3)"
    versionMinor u8        "bitstream version minor (2)"
    versionRev   u8        "bitstream version revision"
}

// Speex header ("Speex   ").
struct SpeexHeader {
    magic                string[8]  "always Speex   "
    version              string[20] "encoder version string"
    versionId            i32        "Speex version id (1)"
    headerSize           i32        "size of this header (80)"
    rate                 i32        "sample rate (Hz)"
    mode                 i32        "0 = narrowband, 1 = wideband, 2 = ultra-wideband"
    modeBitstreamVersion i32        "mode bitstream version"
    channels             i32        "channel count"
    bitrate              i32        "bitrate (-1 = unknown)"
    frameSize            i32        "samples per frame"
    vbr                  i32        "1 = variable bitrate"
    framesPerPacket      i32        "frames per Ogg packet"
    extraHeaders         i32        "additional header packets"
    reserved1            i32
    reserved2            i32
}

struct OggPage {
    capturePattern  string[4]          "always OggS"
    version         u8                 "stream structure version (0)"
    headerType      OggHeaderType      "page flags"
    granulePosition i64                "codec-defined position (samples/frames) at page end"
    serialNumber    u32                "logical bitstream serial number"
    pageSequence    u32                "page sequence number (0 for the first page)"
    checksum        u32                "CRC-32 of the page with this field zeroed"
    pageSegments    u8                 "number of segment table entries"
    segmentTable    u8[pageSegments]   "lacing values: payload bytes per segment (255 = continues)"
    payloadOffset   = 27 + pageSegments
    // The first byte of the payload says which codec's identification header
    // this is. Placed by pointer at the payload start, so it reads no bytes of
    // the header walk itself.
    packetType      at +payloadOffset u8 "first payload byte: 1 Vorbis, 0x4F Opus, 0x7F FLAC, 0x80 Theora, 0x53 Speex"
    identification  at +payloadOffset match packetType {
        1    => VorbisIdentification
        0x4F => OpusHead
        0x7F => OggFlacIdentification
        0x80 => TheoraIdentification
        0x53 => SpeexHeader
        default => bytes[0]
    }
}

// OpenEXR - Industrial Light and Magic's high dynamic range image format, and
// the reason film and VFX work can keep sixteen stops of exposure in a file.
// Little-endian throughout, which is unusual for an image format.
//
// The header is self-describing: attributes are written as name, type name,
// size, value, and a reader skips what it does not recognise. The run ends at
// an attribute whose name is empty - a single NUL byte. Because the names are
// variable-length, attribute values are left as bytes here; their meaning is in
// the type name next to each one.
//
// The attributes a file must carry are channels (a chlist naming each channel
// and its pixel type), compression, dataWindow and displayWindow (box2i),
// lineOrder, pixelAspectRatio, screenWindowCenter and screenWindowWidth. A
// multipart file repeats the whole header once per part.
//
// After the header comes the offset table - one 64-bit file offset per scan
// line block or tile - and then the pixel data itself, which is compressed.

bitfield ExrVersion : u32 {
    version   0..7 // format version, currently 2
    tiled     9    // pixels are stored as tiles rather than scan lines
    longNames 10   // attribute and channel names may exceed 31 characters
    nonImage  11   // deep data: a variable number of samples per pixel
    multiPart 12   // the file holds more than one part, each with its own header
}

// One header attribute: its name, the name of its type, and its value. Both
// names are NUL-terminated, so nothing here is at a fixed offset.
//
// The end of the header is a single NUL where the next name would start. It is
// read first, by pointer, so the terminator costs exactly one byte and the walk
// does not go looking for a type and a size that are not there.
struct ExrAttribute {
    firstByte at +0 u8  "first byte of the name; 0 here ends the header"
    name  cstring       "attribute name, NUL-terminated"
    type  cstring       if firstByte > 0 "type name: box2i, chlist, compression, float, v2f, string, ..."
    size  u32           if firstByte > 0 "bytes of value that follow"
    value bytes[size]   if firstByte > 0 "the value, laid out as its type dictates"
}

struct Exr {
    magic      bytes[4]            "76 2F 31 01, the OpenEXR magic"
    version    ExrVersion          "version number in the low byte, feature flags above it"
    attributes repeat ExrAttribute until firstByte == 0 "header attributes, ending at the single NUL that closes the header"
    // The offset table follows - one 64-bit file offset per scan line block or
    // tile - and then the compressed pixel data.
}

// pcapng — the block-structured capture format Wireshark and dumpcap write by
// default (libpcap's successor). Every block is: type, total length, body, then
// the same total length again, so the file can be walked in either direction.
//
// Each block is walked by its own length, and a pointer-placed `match` decodes
// the body of the common block types without disturbing that walk.

enum PcapngLinkType : u16 {
    Null       = 0
    Ethernet   = 1
    Ppp        = 9
    Raw        = 101
    Ieee80211  = 105
    Loopback   = 108
    LinuxSll   = 113
    Usb        = 189
    Bluetooth  = 201
    LinuxSll2  = 276
}

// Section Header Block — starts every file and every appended section.
struct PcapngShb {
    byteOrderMagic u32 "0x1A2B3C4D; byte-swapped in a big-endian section"
    versionMajor   u16 "major version (1)"
    versionMinor   u16 "minor version (0)"
    sectionLength  i64 "bytes in this section, or -1 when unknown"
}

// Interface Description Block — one per capture interface, in order.
struct PcapngIdb {
    linkType PcapngLinkType "link-layer type of this interface"
    reserved u16
    snapLen  u32            "max captured bytes per packet (0 = no limit)"
}

// Enhanced Packet Block — one captured packet.
struct PcapngEpb {
    interfaceId u32                "index of the interface this arrived on"
    timestampHi u32                "high 32 bits of the timestamp"
    timestampLo u32                "low 32 bits of the timestamp"
    capturedLen u32                "bytes of the packet stored here"
    originalLen u32                "length of the packet on the wire"
    packetData  bytes[capturedLen] "the captured packet bytes"
}

// Simple Packet Block — a packet with no per-packet metadata.
struct PcapngSpb {
    originalLen u32 "length of the packet on the wire"
}

// Name Resolution Block — address to hostname records.
struct PcapngNrb {
    recordType   u16 "1 = IPv4, 2 = IPv6, 0 = end of records"
    recordLength u16 "length of the record value"
}

// Interface Statistics Block — counters for one interface.
struct PcapngIsb {
    interfaceId u32 "index of the interface these stats describe"
    timestampHi u32
    timestampLo u32
}

struct PcapngBlock {
    blockType   u32              "block type (0x0A0D0D0A = section header)"
    blockLength u32              "total block length, both length fields included"
    bodyLen     = blockLength - 12
    body        bytes[bodyLen]   "block body: fixed fields then options"
    trailer     u32              "the total length again, for backwards walking"
    // Typed view of the body. Placed by pointer, so it reads no bytes of its
    // own and the block walk above stays exact whatever the type turns out
    // to be. Options after the fixed fields stay inside `body`.
    decoded at +8 match blockType {
        0x0A0D0D0A => PcapngShb
        1          => PcapngIdb
        3          => PcapngSpb
        4          => PcapngNrb
        5          => PcapngIsb
        6          => PcapngEpb
        default    => bytes[0]
    }
}

struct Pcapng {
    blocks repeat PcapngBlock "every block in the file, in order"
}

// PNG — big-endian throughout. An 8-byte signature, then a chain of chunks:
// a length, a four-character type, that many bytes of data, and a CRC-32 over
// the type and the data. Everything is walked by `length` alone, so unknown
// chunks cost nothing, and the chunk types worth reading are decoded through a
// pointer that consumes no bytes of its own.
//
// The signature is chosen to survive damage: the high bit catches 7-bit
// transfers, and the CR/LF/EOF bytes catch line-ending translation.

enum PngColorType : u8 {
    Grayscale      = 0
    Rgb            = 2
    Palette        = 3
    GrayscaleAlpha = 4
    Rgba           = 6
}

enum PngInterlace : u8 {
    NoInterlace = 0
    Adam7       = 1
}

// IHDR — always the first chunk, and the one that says what the image is.
struct PngIhdr {
    width       u32          "image width (px)"
    height      u32          "image height (px)"
    bitDepth    u8           "bits per sample: 1, 2, 4, 8 or 16"
    colorType   PngColorType "what each pixel stores"
    compression u8           "0 = deflate; no other method is defined"
    filter      u8           "0 = adaptive filtering, five filter types"
    interlace   PngInterlace "interlace method"
}

// pHYs — physical pixel dimensions, the closest thing PNG has to a DPI field.
struct PngPhys {
    pixelsPerUnitX u32 "pixels per unit, x axis"
    pixelsPerUnitY u32 "pixels per unit, y axis"
    unit           u8  "0 = unit unknown (aspect ratio only), 1 = metre"
}

// tIME — last modification time, always UTC.
struct PngTime {
    year   u16 "full year"
    month  u8  "1..12"
    day    u8  "1..31"
    hour   u8  "0..23"
    minute u8  "0..59"
    second u8  "0..60 (60 for a leap second)"
}

// sRGB — declares the image is in the sRGB color space.
struct PngSrgb {
    renderingIntent u8 "0 perceptual, 1 relative, 2 saturation, 3 absolute"
}

// gAMA — image gamma, stored as an integer to avoid floats.
struct PngGama {
    gamma u32 "gamma times 100000 (45455 is the usual 1/2.2)"
}

// acTL — animation control, the chunk that makes a PNG an APNG.
struct PngActl {
    numFrames u32 "number of frames"
    numPlays  u32 "times to loop, 0 for forever"
}

struct PngChunk {
    length u32          "bytes of chunk data; the type and CRC are not counted"
    type   char[4]      "chunk type; a lowercase first letter marks it ancillary"
    data   bytes[length] "chunk data"
    crc    u32          "CRC-32 of the type and the data"
    // Typed view of the data. Placed by pointer, so it reads no bytes of its
    // own and the chunk walk above stays exact whatever the type turns out
    // to be.
    decoded at +8 match type {
        "IHDR" => PngIhdr
        "pHYs" => PngPhys
        "tIME" => PngTime
        "sRGB" => PngSrgb
        "gAMA" => PngGama
        "acTL" => PngActl
        "tEXt" => string[length]
        "zTXt" => string[length]
        "iTXt" => string[length]
        default => bytes[0]
    }
}

struct Png {
    signature bytes[8]        "89 50 4E 47 0D 0A 1A 0A"
    chunks    repeat PngChunk "every chunk in order: IHDR first, IEND last"
}

// A Prefetch file is Windows optimising application startup, and one of the most
// useful artefacts in a forensic timeline as a side effect. When a program runs,
// the cache manager records which files and directories it touched in its first
// ten seconds and writes C:/Windows/Prefetch/NAME-HASH.pf, so the next launch
// can read them in one pass. Those recordings are evidence: the file proves the
// program ran, when it last ran, how many times, and what it loaded.
//
// The format changed with almost every Windows release, and the version field is
// the only way to read it:
//   17  Windows XP and Server 2003
//   23  Windows Vista and Windows 7
//   26  Windows 8.1
//   30  Windows 10 and 11
//
// From Windows 8.1 the file keeps the last eight run times rather than one, so a
// single .pf can show a week of executions. From Windows 10 the whole file is
// compressed with the MAM (LZXPRESS Huffman) wrapper and must be decompressed
// before any of this is visible.
//
// The hash in the file name is computed over the full path of the executable,
// which is why the same binary run from two directories produces two .pf files -
// and why a file whose name hash does not match its stored prefetchHash is worth
// a second look.
//
// The offsets in the file information block point at four sections: the file
// metrics array (one entry per file loaded), the trace chains array (the page
// access pattern), the filename strings (the paths those metrics name), and the
// volumes information (the device paths and their serial numbers and creation
// times).

// Windows XP and Server 2003.
struct PrefetchFileInfo17 {
    metricsOffset      u32      "offset of the file metrics array"
    metricsCount       u32      "entries in it: one per file the program loaded"
    traceChainsOffset  u32      "offset of the trace chains array"
    traceChainsCount   u32      "entries in it"
    filenameStringsOffset u32   "offset of the filename strings the metrics point into"
    filenameStringsSize u32     "bytes of those strings, UTF-16LE"
    volumesInfoOffset  u32      "offset of the volumes information"
    volumesCount       u32      "number of volumes involved"
    volumesInfoSize    u32      "bytes of volumes information"
    lastRunTime        u64      "FILETIME of the last execution, UTC"
    unknown            bytes[16] "unknown"
    runCount           u32      "times this program has run"
    unknown2           u32      "unknown"
}

// Windows Vista and Windows 7: an unknown 64-bit field appears before the run
// time, and the block grows a large unknown tail.
struct PrefetchFileInfo23 {
    metricsOffset      u32      "offset of the file metrics array"
    metricsCount       u32      "entries in it"
    traceChainsOffset  u32      "offset of the trace chains array"
    traceChainsCount   u32      "entries in it"
    filenameStringsOffset u32   "offset of the filename strings"
    filenameStringsSize u32     "bytes of those strings, UTF-16LE"
    volumesInfoOffset  u32      "offset of the volumes information"
    volumesCount       u32      "number of volumes involved"
    volumesInfoSize    u32      "bytes of volumes information"
    unknown            u64      "unknown"
    lastRunTime        u64      "FILETIME of the last execution, UTC"
    unknown2           bytes[16] "unknown"
    runCount           u32      "times this program has run"
    unknown3           u32      "unknown"
    unknown4           bytes[80] "unknown"
}

// Windows 8.1 and Windows 10 / 11: eight run times instead of one. The Windows
// 10 layout matches this one; some later builds use a variant whose block is
// eight bytes shorter, putting runCount at 0xC8 rather than 0xD0.
struct PrefetchFileInfo26 {
    metricsOffset      u32      "offset of the file metrics array"
    metricsCount       u32      "entries in it"
    traceChainsOffset  u32      "offset of the trace chains array"
    traceChainsCount   u32      "entries in it"
    filenameStringsOffset u32   "offset of the filename strings"
    filenameStringsSize u32     "bytes of those strings, UTF-16LE"
    volumesInfoOffset  u32      "offset of the volumes information"
    volumesCount       u32      "number of volumes involved"
    volumesInfoSize    u32      "bytes of volumes information"
    unknown            u64      "unknown"
    lastRunTimes       u64[8]   "the last eight execution times as FILETIMEs, newest first; unused slots are zero"
    unknown2           bytes[16] "unknown"
    runCount           u32      "times this program has run"
    unknown3           u32      "unknown"
    unknown4           u32      "unknown"
    unknown5           bytes[88] "unknown"
}

struct Prefetch {
    version        u32       "format version: 17, 23, 26 or 30 - see the table above"
    signature      char[4]   "SCCA"
    unknown        u32       "unknown; 0x0F, 0x11 or 0x17 in practice"
    fileSize       u32       "size of this prefetch file in bytes"
    executableName bytes[60] "executable file name, UTF-16LE, NUL-terminated, up to 29 characters"
    prefetchHash   u32       "hash of the executable path; the same value appears in the file name"
    unknown2       u32       "unknown flags"
    fileInfo17     PrefetchFileInfo17 if version == 17 "Windows XP file information"
    fileInfo23     PrefetchFileInfo23 if version == 23 "Windows Vista / 7 file information"
    fileInfo26     PrefetchFileInfo26 if version == 26 "Windows 8.1 file information"
    fileInfo30     PrefetchFileInfo26 if version == 30 "Windows 10 / 11 file information"
}

// Photoshop document - big-endian, and unusually tidy for a native application
// format: a fixed 26-byte header, then four sections, each introduced by its
// own length. That means the whole file can be walked without understanding
// any of it, which is what makes the layout below possible.
//
// The sections are, in order: the colour mode data (a palette, for indexed and
// duotone images), the image resources (a grab bag of ICC profiles, guides,
// slices, thumbnails and the like), the layer and mask information, and
// finally the flattened composite image that other applications read.
//
// PSB is the same format with 64-bit lengths, used for documents over 30000
// pixels on a side. Version 2 marks one; the lengths below are the PSD form.

enum PsdColorMode : u16 {
    Bitmap       = 0
    Grayscale    = 1
    Indexed      = 2
    Rgb          = 3
    Cmyk         = 4
    Multichannel = 7
    Duotone      = 8
    Lab          = 9
}

enum PsdCompression : u16 {
    Raw              = 0
    Rle              = 1 // PackBits, per scanline
    ZipNoPrediction  = 2
    ZipWithPrediction = 3
}

struct Psd {
    signature   char[4]  "8BPS"
    version     u16      "1 = PSD, 2 = PSB with 64-bit section lengths"
    reserved    bytes[6] "zero"
    channels    u16      "colour channels including alpha, 1 to 56"
    height      u32      "image height in pixels"
    width       u32      "image width in pixels"
    depth       u16      "bits per channel: 1, 8, 16 or 32"
    colorMode   PsdColorMode "how the channels are interpreted"
    colorDataLength u32  "bytes of colour mode data; 0 unless indexed or duotone"
    colorData   bytes[colorDataLength] "the palette, for indexed and duotone images"
    resourcesLength u32  "bytes of image resources"
    resources   bytes[resourcesLength] "8BIM resource blocks: profiles, guides, thumbnail"
    layerMaskLength u32  "bytes of layer and mask information"
    layerMask   bytes[layerMaskLength] "the layer records, channel data and masks"
    compression PsdCompression "how the composite image below is packed"
    imageData   bytes[*] "the flattened composite, one plane per channel"
}

// QCOW2 - QEMU's copy-on-write disk image, and the format behind most Linux
// virtual machine disks. Big-endian throughout, which is unusual for a format
// that almost only ever runs on little-endian hardware.
//
// The guest disk is divided into clusters (65536 bytes by default) and mapped
// through two levels of tables: an L1 table, whose entries point at L2 tables,
// whose entries point at the clusters holding the data. An unallocated entry is
// zero, which is what makes a sparse image small: only written clusters exist.
//
// A second structure, the refcount table, counts references to each cluster.
// That is what internal snapshots are built on - a snapshot bumps the count on
// every cluster it shares, and a write to a cluster with a count above one
// copies it first.
//
// backingFileOffset points at a path string elsewhere in the image. When set,
// this image holds only the differences from that file, which is how a chain of
// images built on one base disk works.
//
// Version 3 added the three feature words below. The rule is what makes them
// useful: a reader that does not understand an incompatible bit must refuse the
// image, one that does not understand a compatible bit may proceed, and an
// autoclear bit it does not understand must be cleared on write.

enum Qcow2CryptMethod : u32 {
    NoEncryption = 0
    Aes          = 1 // the old, broken AES-CBC scheme; qemu will not create it
    Luks         = 2 // LUKS, with the key material stored in the image
}

bitfield Qcow2IncompatibleFeatures : u64 {
    dirty       0 // the refcounts may be wrong; the image needs a repair pass
    corrupt     1 // the image is known corrupt and must not be written
    externalData 2 // guest data lives in an external file, not in this one
    compressionType 3 // a compression type other than zlib is in use
    extendedL2  4 // L2 entries are 128-bit and carry subcluster bitmaps
}

bitfield Qcow2CompatibleFeatures : u64 {
    lazyRefcounts 0 // refcounts are only flushed on clean shutdown
}

bitfield Qcow2AutoclearFeatures : u64 {
    bitmaps      0 // the image carries persistent dirty bitmaps
    rawExternalData 1 // the external data file can be read as a raw image
}

struct Qcow2 {
    magic              bytes[4]          "51 46 49 FB, the ASCII QFI followed by 0xFB"
    version            u32               "2 or 3"
    backingFileOffset  u64               "offset of the backing file path string, 0 if this image stands alone"
    backingFileSize    u32               "length of that path in bytes, no terminator"
    clusterBits        u32               "cluster size as a power of two; 16 means 65536 bytes"
    size               u64               "virtual disk size the guest sees, in bytes"
    cryptMethod        Qcow2CryptMethod  "how guest data is encrypted"
    l1Size             u32               "entries in the L1 table"
    l1TableOffset      u64               "offset of the L1 table; cluster aligned"
    refcountTableOffset u64              "offset of the refcount table; cluster aligned"
    refcountTableClusters u32            "clusters occupied by the refcount table"
    nbSnapshots        u32               "number of internal snapshots"
    snapshotsOffset    u64               "offset of the snapshot table"
    incompatibleFeatures Qcow2IncompatibleFeatures if version >= 3 "bits a reader must understand or refuse the image"
    compatibleFeatures Qcow2CompatibleFeatures    if version >= 3 "bits a reader may safely ignore"
    autoclearFeatures  Qcow2AutoclearFeatures     if version >= 3 "bits a writer must clear if it does not understand them"
    refcountOrder      u32 if version >= 3 "refcount width as a power of two; 4 means 16-bit refcounts"
    headerLength       u32 if version >= 3 "bytes of header, 104 or more; extensions follow it"
    // Header extensions start at headerLength and are typed records: a 32-bit
    // magic, a 32-bit length, then the payload. They carry the backing file
    // format string, feature name table, and encryption header pointer.
    l1Table at l1TableOffset u64[l1Size] "the L1 table: each entry points at an L2 table, 0 when nothing below it is allocated"
}

// QOI (Quite OK Image) — big-endian header + opaque encoded stream.
struct Qoi {
    magic      char[4]  "magic 'qoif'"
    width      u32      "image width in pixels (big-endian)"
    height     u32      "image height in pixels"
    channels   u8       "3 = RGB, 4 = RGBA"
    colorspace u8       "0 = sRGB with linear alpha, 1 = all linear"
    pixels     bytes[*] "encoded chunk stream, ending in 00 00 00 00 00 00 00 01"
}

// RAR 5.0 — an 8-byte signature, then a sequence of blocks. Every block is a
// CRC-32, a variable-length header size, and the header; most block fields
// are vints: 7 bits per byte with a continuation high bit, which is exactly
// LEB128 (varint here).
//
// The header size counts from the header type to the end of the extra area,
// and its own encoded width varies, so a generic block walk is not possible
// declaratively. This pack decodes the main archive header and the first file
// header — which for a typical archive is the interesting part.

// Header flags are vints too, but all defined bits fit in one byte.
bitfield Rar5HeaderFlags : u8 {
    extraArea         0 // an extra area follows the header fields
    dataArea          1 // a data area follows the header
    skipIfUnknown     2 // blocks with unknown type may be skipped
    dataContinues     3 // data continues from the previous volume
    dataContinuesNext 4 // data continues in the next volume
    dependsOnPrev     5 // block depends on the preceding block
    preserveChild     6 // preserve a child block if the host is modified
}

bitfield Rar5ArchiveFlags : u8 {
    volume       0 // part of a multi-volume set
    volumeNumber 1 // a volume number field follows
    solid        2 // solid archive
    recovery     3 // recovery record present
    locked       4 // archive is locked
}

bitfield Rar5FileFlags : u8 {
    directory       0 // entry is a directory
    timePresent     1 // a modification time (Unix seconds) follows
    crcPresent      2 // a CRC-32 of the unpacked data follows
    unpackedUnknown 3 // unpacked size is unknown
}

enum Rar5HeaderType : u8 {
    Main       = 1
    File       = 2
    Service    = 3
    Encryption = 4
    EndArchive = 5
}

struct Rar5MainHeader {
    crc          u32              "CRC-32 of the header (size field onwards)"
    headerSize   varint           "header size from the type field to the end of the extra area"
    headerType   Rar5HeaderType   "1 = main archive header"
    headerFlags  Rar5HeaderFlags  "common header flags"
    extraSize    varint           if headerFlags.extraArea "extra area size"
    archiveFlags Rar5ArchiveFlags "archive-level flags"
    volumeNumber varint           if archiveFlags.volumeNumber "volume number (0-based)"
}

struct Rar5FileHeader {
    crc             u32             "CRC-32 of the header (size field onwards)"
    headerSize      varint          "header size from the type field to the end of the extra area"
    headerType      Rar5HeaderType  "2 = file header, 3 = service header"
    headerFlags     Rar5HeaderFlags "common header flags"
    extraSize       varint          if headerFlags.extraArea "extra area size (timestamps, hashes, ...)"
    dataSize        varint          if headerFlags.dataArea  "packed data size following the header"
    fileFlags       Rar5FileFlags   "file-specific flags"
    unpackedSize    varint          "unpacked file size"
    attributes      varint          "OS-specific file attributes"
    mtime           u32             if fileFlags.timePresent "modification time, Unix seconds"
    dataCrc         u32             if fileFlags.crcPresent  "CRC-32 of the unpacked data"
    compressionInfo varint          "bits 0-5 version, 6 solid, 7-9 method (0 = store), 10-13 dictionary size"
    hostOs          varint          "0 = Windows, 1 = Unix"
    nameLength      varint          "file name length in bytes"
    name            string[nameLength] "file name (UTF-8, / separated)"
}

struct Rar5 {
    signature bytes[8]       "52 61 72 21 1A 07 01 00"
    main      Rar5MainHeader "main archive header"
    // The main header is tiny, so its size vint is a single byte: the next
    // block starts at 8 (signature) + 4 (crc) + 1 (size vint) + headerSize.
    firstFilePos = main.headerSize + 13
    firstFile at firstFilePos Rar5FileHeader "first file (or service) header"
}

// Windows registry hive - the on-disk form of SYSTEM, SOFTWARE, SAM, SECURITY
// and every NTUSER.DAT. A 4 KiB base block, then the hive bins: 4 KiB-aligned
// containers carved into cells, which are the keys, values, subkey lists and
// security descriptors the registry is made of.
//
// Offsets inside a hive are relative to the start of the bins data at 4096,
// not to the start of the file, so reaching the root key means adding 4096 to
// rootCellOffset. That is done below, and the root key cell is followed there.
//
// The two sequence numbers are how a torn write is detected. They are equal in
// a cleanly closed hive; when they differ, the hive was being written when the
// machine stopped and the .LOG file next to it holds the missing pages.
//
// A cell size is signed, and the sign is the allocation bit: negative means
// the cell is in use and positive means it is free. Its absolute value is the
// cell length, so a deleted key often survives intact until its space is
// reused - which is why carving unallocated cells is standard practice in
// registry forensics.

enum RegfFileType : u32 {
    Primary          = 0
    TransactionLog   = 1
    TransactionLog2  = 2
    TransactionLog3  = 6
}

bitfield RegfKeyFlags : u16 {
    volatile     0 // the key is not written to disk
    hiveExit     1 // a mount point into another hive
    hiveEntry    2 // the root of a mounted hive
    noDelete     3
    symlink      4 // a REG_LINK to another key
    compName     5 // the key name is ASCII rather than UTF-16
    predefined   6
}

// An nk cell: one registry key, with its subkey and value lists.
struct RegfNamedKey {
    signature        char[2]      "nk"
    flags            RegfKeyFlags "key type and name encoding"
    lastWritten      u64          "last write time (FILETIME)"
    accessBits       u32          "access flags"
    parent           u32          "offset of the parent key cell"
    subkeyCount      u32          "stable subkeys"
    volatileSubkeys  u32          "volatile subkeys, absent from the file"
    subkeyList       u32          "offset of the subkey list cell"
    volatileSubkeyList u32        "offset of the volatile subkey list"
    valueCount       u32          "values on this key"
    valueList        u32          "offset of the value list cell"
    security         u32          "offset of the security descriptor cell"
    classNameOffset  u32          "offset of the class name, or 0xFFFFFFFF"
    maxSubkeyNameLen u32          "longest subkey name, in bytes"
    maxSubkeyClassLen u32         "longest subkey class name"
    maxValueNameLen  u32          "longest value name, in bytes"
    maxValueDataLen  u32          "largest value data"
    workVar          u32          "scratch space used at run time"
    keyNameLength    u16          "length of the name that follows, in bytes"
    classNameLength  u16          "length of the class name"
    keyName          char[keyNameLength] "the key name, ASCII when compName is set"
}

// A hive bin: a 4 KiB-aligned container the cells are carved out of.
struct RegfHbin {
    signature char[4]  "hbin"
    offset    u32      "offset of this bin from the start of the bins data"
    size      u32      "size of this bin, always a multiple of 4096"
    reserved  bytes[8] "zero"
    timestamp u64      "last write time (FILETIME); meaningful in the first bin only"
    spare     u32      "offset of the next bin, in some versions"
    cellsLen  = size - 32
    cells     bytes[cellsLen] "the cells: nk keys, vk values, sk descriptors, lists"
}

struct Regf {
    signature        char[4]      "regf"
    primarySequence  u32          "incremented before a write"
    secondarySequence u32         "incremented after it; equal to the primary when clean"
    lastWritten      u64          "last write time (FILETIME)"
    majorVersion     u32          "1"
    minorVersion     u32          "3 or 5 on modern Windows"
    fileType         RegfFileType "primary hive or transaction log"
    fileFormat       u32          "1, direct memory load"
    rootCellOffset   u32          "offset of the root key cell, from the start of the bins"
    hiveBinsDataSize u32          "total size of the hive bins"
    clusteringFactor u32          "1, in units of 512 bytes"
    fileName         char[64]     "last 31 characters of the hive path, UTF-16"
    reserved         bytes[396]   "RmId, LogId and flags on newer versions, else zero"
    checksum         u32          "XOR of the first 508 bytes, taken 4 bytes at a time"
    reserved2        bytes[3576]  "zero"
    bootType         u32          "set during boot, zero in a hive at rest"
    bootRecover      u32          "set during boot, zero in a hive at rest"
    rootCellPos      = rootCellOffset + 4096
    rootKeyPos       = rootCellOffset + 4100
    // The root key, followed to its cell. Offsets in a hive are relative to
    // the bins data at 4096, so that is added above. The 4 bytes at the cell
    // start are its signed size; the nk record begins right after them.
    rootCellSize at rootCellPos i32 "cell size; negative means the cell is allocated"
    rootKey      at rootKeyPos RegfNamedKey "the root key of this hive"
    bins         repeat RegfHbin "every hive bin, in file order"
}

// An RPM package is four parts, in order: a 96-byte lead, a signature header, a
// main header, and then a compressed cpio archive holding the files. Everything
// is big-endian, which is a legacy of RPM's first port.
//
// The lead is obsolete - rpm has ignored most of it since version 4 - but it is
// still written, and it is still what file(1) matches on. The real metadata is
// in the two headers, which share one structure: a magic, a count of index
// entries, and the size of the data blob those entries point into. Each entry
// says which tag it is, its type, its offset into the blob, and how many values
// it has.
//
// This pack decodes the lead and the signature header's index. The main header
// follows the signature header on an 8-byte boundary, and its offset depends on
// the signature data size, so it is not reachable declaratively.
//
// Tags worth recognising in the signature header: 1000 is the package size,
// 1004 an MD5 digest, 1002 a PGP signature over the main header and payload,
// 269 a SHA-1 of the header, 273 an OpenPGP signature of the header.

enum RpmType : u16 {
    Binary = 0 // a package of built files
    Source = 1 // a source package, a .src.rpm
}

enum RpmSignatureType : u16 {
    HeaderSignature = 5 // the only value rpm accepts: signatures live in a header structure
}

enum RpmTagType : u32 {
    Null        = 0
    Char        = 1
    Int8        = 2
    Int16       = 3
    Int32       = 4
    Int64       = 5
    String      = 6 // one NUL-terminated string
    Bin         = 7 // opaque bytes: digests, signatures
    StringArray = 8 // count NUL-terminated strings
    I18nString  = 9 // a string with translations, indexed by the locale table
}

// The lead. Kept for compatibility; rpm trusts the headers instead.
struct RpmLead {
    magic       bytes[4]         "ED AB EE DB"
    major       u8               "format major version, 3 or 4"
    minor       u8               "format minor version, 0"
    type        RpmType          "binary or source package"
    archNum     u16              "architecture the package was built for, an rpm-internal number"
    name        string[66]       "package name and version, NUL-padded"
    osNum       u16              "target operating system, an rpm-internal number (1 is Linux)"
    signatureType RpmSignatureType "how the signature is stored; always 5"
    reserved    bytes[16]        "reserved, zero"
}

// One index entry. The offset is into the data blob that follows the index, not
// into the file.
struct RpmIndexEntry {
    tag    i32       "which piece of metadata this is"
    type   RpmTagType "how the value is stored"
    offset i32       "offset of the value within the data blob"
    count  u32       "number of values of that type"
}

// A header structure: magic, index, then the blob the index points into. Both
// the signature header and the main header use it.
struct RpmHeader {
    magic     bytes[3]              "8E AD E8"
    version   u8                    "header structure version, 1"
    reserved  bytes[4]              "reserved, zero"
    numIndex  u32                   "index entries that follow"
    dataSize  u32                   "bytes of data blob after the index"
    index     RpmIndexEntry[numIndex] "the index: one entry per tag present"
    data      bytes[dataSize]       "the blob every entry above points into"
}

struct Rpm {
    lead      RpmLead   "the obsolete but still written 96-byte lead"
    signature RpmHeader "the signature header: digests and signatures over the rest of the file"
    // The main header starts at the next 8-byte boundary after the signature
    // header, so where it lands depends on dataSize above; the compressed cpio
    // payload follows it.
}

// SQLite 3 - a 100-byte header, then a run of fixed-size pages. Everything
// multi-byte in the file is big-endian, including on little-endian machines.
//
// Page 1 is special: it carries the header in its first 100 bytes and then the
// b-tree page header of sqlite_schema, the table that stores the CREATE
// statements for everything else. So the b-tree header below starts at offset
// 100, not at the start of the page.
//
// Two numbers are worth knowing. pageSize is stored as a u16, so 65536 could
// not fit and is encoded as 1. cellContentOffset has the same problem and the
// same answer. A file whose header says pageSize 1 has 64 KiB pages.

enum SqliteEncoding : u32 {
    Utf8    = 1
    Utf16le = 2
    Utf16be = 3
}

enum SqliteSchemaFormat : u32 {
    Format1 = 1 // the original format
    Format2 = 2 // usable ALTER TABLE ADD COLUMN
    Format3 = 3 // non-NULL default values in added columns
    Format4 = 4 // DESC indexes and the boolean/blob type affinities
}

enum SqliteVersion : u8 {
    Legacy = 1 // rollback journal
    Wal    = 2 // write-ahead log
}

enum SqliteBtreeType : u8 {
    InteriorIndex = 2
    InteriorTable = 5
    LeafIndex     = 10
    LeafTable     = 13
}

struct SqliteHeader {
    magic                char[16]           "SQLite format 3, NUL-terminated"
    pageSize             u16                "page size in bytes; 1 encodes 65536"
    writeVersion         SqliteVersion      "write format: rollback journal or WAL"
    readVersion          SqliteVersion      "read format"
    reservedSpace        u8                 "bytes reserved at the end of every page"
    maxPayloadFraction   u8                 "always 64"
    minPayloadFraction   u8                 "always 32"
    leafPayloadFraction  u8                 "always 32"
    fileChangeCounter    u32                "incremented on every transaction"
    databaseSize         u32                "size of the database in pages"
    firstFreelistPage    u32                "page number of the first freelist trunk page"
    freelistPageCount    u32                "pages on the freelist"
    schemaCookie         u32                "incremented whenever the schema changes"
    schemaFormat         SqliteSchemaFormat "schema layer file format"
    defaultPageCacheSize u32                "suggested page cache size"
    largestRootBtreePage u32                "non-zero only in auto-vacuum databases"
    textEncoding         SqliteEncoding     "encoding of all text in the database"
    userVersion          u32                "set by PRAGMA user_version; SQLite never reads it"
    incrementalVacuum    u32                "non-zero for incremental-vacuum mode"
    applicationId        u32                "set by PRAGMA application_id, for file(1)"
    reserved             bytes[20]          "reserved for expansion, zero"
    versionValidFor      u32                "the change counter that sqliteVersion belongs to"
    sqliteVersion        u32                "SQLITE_VERSION_NUMBER of the library that last wrote"
}

// The b-tree page header. On page 1 it starts at offset 100, right after the
// database header; on every other page it starts at offset 0.
struct SqliteBtreePage {
    type                SqliteBtreeType "interior or leaf, index or table"
    firstFreeblock      u16 "offset of the first free block, 0 if there is none"
    cellCount           u16 "cells on this page"
    cellContentOffset   u16 "start of the cell content area; 0 encodes 65536"
    fragmentedFreeBytes u8  "fragmented free bytes in the cell content area"
    // Interior pages (types 2 and 5) carry a right-most child pointer; leaf
    // pages (10 and 13) do not.
    rightmostPointer u32 if type < 10 "page number of the right-most child"
    cellPointers     u16[cellCount] "offsets of each cell, in key order"
}

struct Sqlite {
    header SqliteHeader    "the 100-byte database header"
    page1  SqliteBtreePage "b-tree header of page 1: the root of sqlite_schema"
}

// The -wal sidecar SQLite writes in WAL mode: a 32-byte header, then frames,
// each a 24-byte frame header followed by one full page image. A frame counts
// only if its salts match the header and its checksum chain holds, so a log
// can hold stale frames left over from an earlier checkpoint.
//
// Every frame is 24 + pageSize bytes, so the whole log is a flat array once
// you know pageSize. The first frame is decoded here; the rest follow at that
// stride.

struct SqliteWalFrameHeader {
    pageNumber  u32 "database page this frame replaces"
    dbSizeAfter u32 "database size in pages after a commit frame, else 0"
    salt1       u32 "copy of the header salt-1; a mismatch marks the frame stale"
    salt2       u32 "copy of the header salt-2"
    checksum1   u32 "running checksum over the frame header and the page"
    checksum2   u32 "second half of the running checksum"
}

struct SqliteWal {
    magic         u32 "0x377F0682 or 0x377F0683; the low bit gives the checksum byte order"
    formatVersion u32 "3007000"
    pageSize      u32 "database page size; every frame is 24 bytes longer than this"
    checkpointSeq u32 "checkpoint sequence number"
    salt1         u32 "random, changed on every checkpoint"
    salt2         u32 "random, changed on every checkpoint"
    checksum1     u32 "checksum of the first 24 bytes of this header"
    checksum2     u32 "second half of that checksum"
    firstFrame    SqliteWalFrameHeader "header of the first frame in the log"
    firstPage     bytes[pageSize]      "the page image that frame carries"
}

// The -journal sidecar SQLite writes in the default rollback mode: the header
// records what the database looked like before the transaction, and each
// record holds one original page to put back if the transaction is rolled
// back. A journal whose pageCount is 0xFFFFFFFF ran to the end of the file.
//
// The header is padded out to sectorSize before the first record, so the
// records do not start at offset 28. Each record is 8 + pageSize bytes; the
// first is decoded here and the rest follow at that stride.

struct SqliteJournal {
    magic        bytes[8] "D9 D5 05 F9 20 A1 63 D7"
    pageCount    u32 "records that follow, or 0xFFFFFFFF for all of them"
    nonce        u32 "checksum seed for the records"
    initialSize  u32 "database size in pages before the transaction"
    sectorSize   u32 "assumed sector size; the header is padded out to this"
    pageSize     u32 "database page size"
    padLen       = sectorSize - 28
    padding      bytes[padLen] "zero padding up to the first sector boundary"
    firstPageNumber u32 "database page the first record restores"
    firstPage    bytes[pageSize] "that page as it was before the transaction"
    firstChecksum u32 "checksum of the page, seeded with the nonce"
}

struct TiffEntry {
    tag         u16 "field tag (identifies the metadata field)"
    fieldType   u16 "1=byte 2=ascii 3=short 4=long 5=rational"
    count       u32 "number of values"
    valueOffset u32 "the value itself, or an offset to it"
}

struct TiffIfd {
    numEntries u16 "number of directory entries"
    entries    TiffEntry[numEntries] "image file directory entries"
    nextIfd    u32 "offset of the next IFD (0 if this is the last)"
}

struct Tiff {
    byteOrder u16 "0x4949 (II) little-endian or 0x4D4D (MM) big-endian"
    magic     u16 "42, the TIFF version answer"
    ifdOffset u32 "offset of the first image file directory"
    ifd       at ifdOffset TiffIfd "first image file directory"
}

struct TiffEntry {
    tag         u16 "field tag (identifies the metadata field)"
    fieldType   u16 "1=byte 2=ascii 3=short 4=long 5=rational"
    count       u32 "number of values"
    valueOffset u32 "the value itself, or an offset to it"
}

struct TiffIfd {
    numEntries u16 "number of directory entries"
    entries    TiffEntry[numEntries] "image file directory entries"
    nextIfd    u32 "offset of the next IFD (0 if this is the last)"
}

struct Tiff {
    byteOrder u16 "0x4949 (II) little-endian or 0x4D4D (MM) big-endian"
    magic     u16 "42, the TIFF version answer"
    ifdOffset u32 "offset of the first image file directory"
    ifd       at ifdOffset TiffIfd "first image file directory"
}

// USD crate - the binary form of Pixar's Universal Scene Description, the scene
// format the film industry standardised on. A .usd file may be this, or the text
// .usda form; .usdc is always this, and .usdz is a zip of both.
//
// The layout is unusual and deliberate: the file is read back to front. The
// first 88 bytes are the bootstrap, whose only real payload is tocOffset - the
// offset of the table of contents, which sits at the end of the file. The table
// lists the sections (TOKENS, STRINGS, FIELDS, FIELDSETS, PATHS, SPECS) and
// where each one starts.
//
// That ordering is what makes a crate file cheap to open. A consumer reads the
// bootstrap, jumps to the table, and then loads only the sections it needs -
// so a renderer can resolve one prim out of a scene of millions without
// touching the rest. It also means data can be appended and the table rewritten
// without moving anything.
//
// Each table entry is a 16-byte name, a 64-bit offset and a 64-bit size, so the
// table itself is a count followed by fixed-size records - but it lives at
// tocOffset, which points near the end of the file rather than forward from
// here.

struct Usdc {
    ident     char[8]  "PXR-USDC"
    version   bytes[8] "major, minor and patch in the first three bytes; the rest reserved"
    tocOffset i64      "offset of the table of contents, near the end of the file"
    reserved  i64[8]   "reserved, zero"
}

// VHDX - the Hyper-V virtual disk, also what Windows mounts natively and what
// WSL2 keeps each distro's filesystem in. The first megabyte is a fixed header
// section of five 64 KiB slots: the file identifier, two copies of the header,
// and two copies of the region table. Writers update the two headers
// alternately, and the one with the higher sequence number is current, so a
// crash mid-write always leaves one good copy.
//
// The region table locates the two required regions by GUID: the metadata
// region (disk size, block size, sector sizes) and the BAT, the block
// allocation table mapping each payload block of the virtual disk to a
// position in the file. GUIDs are told apart here by their first 32-bit word.
//
// The header and region table checksums are CRC-32C (Castagnoli), which is
// not the CRC-32 Nybble can verify, so they are shown but not checked.

enum VhdxRegion : u32 {
    Bat      = 0x2DC27766 // 2DC27766-F623-4200-9D64-115E9BFD4A08
    Metadata = 0x8B7CA206 // 8B7CA206-4790-4B9A-B8FE-575F050F886E
}

enum VhdxMetadataItem : u32 {
    FileParameters     = 0xCAA16737
    VirtualDiskSize    = 0x2FA54224
    Page83Data         = 0xBECA12AB
    LogicalSectorSize  = 0x8141BF1D
    PhysicalSectorSize = 0xCDA348C7
    ParentLocator      = 0xA8D35F2B
}

bitfield VhdxFileParameterFlags : u32 {
    leaveBlocksAllocated 0 // a fixed disk: every block is allocated up front
    hasParent            1 // a differencing disk; reads fall through to a parent
}

bitfield VhdxMetadataFlags : u32 {
    isUser        0 // a user-defined item rather than a system one
    isVirtualDisk 1 // describes the virtual disk, so it is copied with it
    isRequired    2 // a reader that does not understand the item must fail
}

// One BAT entry: a payload block's state and where it sits in the file.
bitfield VhdxBatEntry : u64 {
    state        0..2  // 0 not present, 2 undefined, 3 zero, 6 fully present, 7 partially present
    fileOffsetMb 20..63 // file offset of the block, in megabytes
}

struct VhdxFileParameters {
    blockSize u32                    "payload block size in bytes, 1 to 256 MiB (32 MiB by default)"
    flags     VhdxFileParameterFlags
}

struct VhdxMetadataEntry {
    itemId   VhdxMetadataItem "first word of the item's GUID"
    itemIdRest bytes[12]      "rest of the GUID"
    offset   u32              "offset of the value from the start of the metadata region"
    length   u32              "bytes of the value"
    flags    VhdxMetadataFlags
    reserved u32
}

// The metadata table. Values are placed relative to the start of the region,
// which is this struct's start, so they are read from here. Every disk has at
// least the five system items; a differencing disk adds a parent locator as a
// sixth entry, listed but not decoded.
struct VhdxMetadataTable {
    signature  char[8]  "metadata"
    reserved   u16
    entryCount u16      "items in the table"
    reserved2  bytes[20]
    entry0     VhdxMetadataEntry
    entry1     VhdxMetadataEntry
    entry2     VhdxMetadataEntry
    entry3     VhdxMetadataEntry
    entry4     VhdxMetadataEntry
    entry5     VhdxMetadataEntry if entryCount >= 6
    value0At   = entry0.offset
    value0 at +value0At match entry0.itemId {
        0xCAA16737 => VhdxFileParameters
        0x2FA54224 => u64
        0xBECA12AB => bytes[16]
        0x8141BF1D => u32
        0xCDA348C7 => u32
        default    => bytes[0]
    }
    value1At   = entry1.offset
    value1 at +value1At match entry1.itemId {
        0xCAA16737 => VhdxFileParameters
        0x2FA54224 => u64
        0xBECA12AB => bytes[16]
        0x8141BF1D => u32
        0xCDA348C7 => u32
        default    => bytes[0]
    }
    value2At   = entry2.offset
    value2 at +value2At match entry2.itemId {
        0xCAA16737 => VhdxFileParameters
        0x2FA54224 => u64
        0xBECA12AB => bytes[16]
        0x8141BF1D => u32
        0xCDA348C7 => u32
        default    => bytes[0]
    }
    value3At   = entry3.offset
    value3 at +value3At match entry3.itemId {
        0xCAA16737 => VhdxFileParameters
        0x2FA54224 => u64
        0xBECA12AB => bytes[16]
        0x8141BF1D => u32
        0xCDA348C7 => u32
        default    => bytes[0]
    }
    value4At   = entry4.offset
    value4 at +value4At match entry4.itemId {
        0xCAA16737 => VhdxFileParameters
        0x2FA54224 => u64
        0xBECA12AB => bytes[16]
        0x8141BF1D => u32
        0xCDA348C7 => u32
        default    => bytes[0]
    }
}

// The start of the BAT. It interleaves payload entries with sector bitmap
// entries (one per chunk of blocks, used only by differencing disks); the
// first 32 entries are shown.
struct VhdxBat {
    entries VhdxBatEntry[32]
}

struct VhdxRegionEntry {
    guid       VhdxRegion "first word of the region's GUID"
    guidRest   bytes[12]  "rest of the GUID"
    fileOffset u64        "offset of the region, 1 MiB aligned"
    length     u32        "bytes in the region, a multiple of 1 MiB"
    required   u32        "bit 0: a reader that does not know this region must fail"
    region at fileOffset match guid {
        0x8B7CA206 => VhdxMetadataTable
        0x2DC27766 => VhdxBat
        default    => bytes[0]
    }
}

struct VhdxRegionTable {
    signature  char[4] "regi"
    checksum   u32     "CRC-32C of the 64 KiB table"
    entryCount u32     "regions listed, at most 2047"
    reserved   u32
    entries    VhdxRegionEntry[entryCount]
}

struct VhdxHeader {
    signature      char[4]   "head"
    checksum       u32       "CRC-32C of the 4 KiB header"
    sequenceNumber u64       "the copy with the higher number is current"
    fileWriteGuid  bytes[16] "changes the first time the file is opened for writing"
    dataWriteGuid  bytes[16] "changes when the disk's contents change"
    logGuid        bytes[16] "all zero unless the log holds entries to replay"
    logVersion     u16       "0"
    version        u16       "1"
    logLength      u32       "bytes in the log, a multiple of 1 MiB"
    logOffset      u64       "offset of the log, 1 MiB aligned"
}

struct Vhdx {
    signature    char[8]   "vhdxfile"
    creator      bytes[512] "the creating application's name, UTF-16LE"
    header1      at 65536  VhdxHeader      "first header copy"
    header2      at 131072 VhdxHeader      "second header copy"
    regionTable  at 196608 VhdxRegionTable "region table"
    regionTable2 at 262144 VhdxRegionTable "backup region table"
}

// VMDK - VMware's virtual disk, also used by VirtualBox and most OVA
// appliances. A .vmdk is either a small text descriptor that names separate
// extent files, or, as here, a sparse extent: a binary header, then usually
// the descriptor text embedded right after it, then the grain tables and
// grains. Every offset in the header counts 512-byte sectors.
//
// The guest disk is cut into grains (64 KiB by default) mapped through two
// levels: the grain directory points at grain tables, whose entries point at
// the sectors holding each grain. A zero entry is a grain never written, which
// is what keeps a fresh image small.
//
// Stream-optimized disks (the kind inside an OVA) compress every grain and
// write the grain directory at the end, flagging gdOffset as all ones; the
// directory is only followed here for uncompressed images.

bitfield VmdkFlags : u32 {
    validNewlineTest   0  // the newline characters below are checked
    redundantGrainTable 1 // a second grain directory and tables are kept
    zeroedGrainGte     2  // grain table entries may mark a grain as zeroed
    compressedGrains   16 // grains are deflate-compressed
    markers            17 // the stream carries typed markers between grains
}

enum VmdkCompression : u16 {
    None    = 0
    Deflate = 1
}

// Read at the grain directory: its first entry, and the table it names. Grain
// tables always hold 512 entries in practice (numGtesPerGt).
struct VmdkFirstTable {
    sector u32 "sector of the first grain table"
    start  = sector * 512
    table  at start u32[512] "the sector of each grain, 0 if never written"
}

struct Vmdk {
    magic              char[4]  "KDMV"
    version            u32      "1, or 2/3 for disks with newer features"
    flags              VmdkFlags
    capacity           u64      "virtual disk size in sectors"
    grainSize          u64      "sectors per grain, 128 (64 KiB) by default"
    descriptorOffset   u64      "sector of the embedded descriptor, 0 if none"
    descriptorSize     u64      "sectors reserved for the descriptor"
    numGtesPerGt       u32      "entries per grain table, 512"
    rgdOffset          u64      "sector of the redundant grain directory"
    gdOffset           u64      "sector of the grain directory"
    overhead           u64      "sectors before the first grain: header, descriptor and tables"
    uncleanShutdown    u8       "1 if the disk was not closed cleanly"
    singleEndLineChar  char     "newline, to catch text-mode corruption"
    nonEndLineChar     char     "space"
    doubleEndLineChar1 char     "carriage return"
    doubleEndLineChar2 char     "newline"
    compressAlgorithm  VmdkCompression
    pad                bytes[433]
    descriptorStart = descriptorOffset * 512
    descriptorBytes = descriptorSize * 512
    descriptor at descriptorStart string[descriptorBytes] if descriptorOffset "the text descriptor: extents, geometry and the parent chain"
    grainsPerTable  = grainSize * numGtesPerGt
    gdEntries       = (capacity + grainsPerTable - 1) / grainsPerTable
    gdStart         = gdOffset * 512
    grainDirectory at gdStart u32[gdEntries] if compressAlgorithm == 0 "sector of each grain table"
    firstGrainTable at gdStart VmdkFirstTable if compressAlgorithm == 0 "the grain table the directory's first entry points at"
}

// WAD - Where's All the Data, the archive id Software shipped Doom in, and the
// reason a thirty-year-old game still has a modding scene. The format is about
// as small as an archive format can be: a twelve-byte header, the lumps
// themselves, and a directory at the end saying where each one starts.
//
// The directory living at the end is what makes a WAD append-friendly: new
// lumps are written over the old directory and a fresh directory goes after
// them, so building a PWAD never rewrites what came before.
//
// A lump is just bytes; the name says what it is. Levels are a run of lumps
// after a map marker - ExMy or MAPxx, then THINGS, LINEDEFS, SIDEDEFS, VERTEXES,
// SEGS, SSECTORS, NODES, SECTORS, REJECT, BLOCKMAP. Markers like S_START and
// S_END bracket the sprites, P_START and P_END the wall patches, and those
// markers are zero-length lumps: the name is the whole content.
//
// An IWAD is a complete game (doom.wad, doom2.wad). A PWAD is a patch: the
// engine loads it after the IWAD, and a lump in it replaces the IWAD lump of the
// same name.

struct WadLump {
    filePos u32       "file offset where this lump's data starts"
    size    u32       "bytes of data; 0 for a marker lump, whose name is its whole purpose"
    name    string[8] "lump name, uppercase ASCII, NUL-padded rather than terminated"
}

struct Wad {
    identification char[4] "IWAD for a complete game, PWAD for a patch"
    numLumps       u32     "number of lumps, and so of directory entries"
    infoTableOfs   u32     "file offset of the directory, which sits after the lump data"
    directory at infoTableOfs WadLump[numLumps] "every lump in the file, in load order"
}

// The patch flavour of the WAD format: identical layout, different magic. The
// engine loads a PWAD after the IWAD, and any lump whose name matches one
// already loaded replaces it - which is how a single level or texture pack can
// override part of a game without touching it.

struct WadLump {
    filePos u32       "file offset where this lump's data starts"
    size    u32       "bytes of data; 0 for a marker lump"
    name    string[8] "lump name, uppercase ASCII, NUL-padded rather than terminated"
}

struct Wad {
    identification char[4] "PWAD"
    numLumps       u32     "number of lumps, and so of directory entries"
    infoTableOfs   u32     "file offset of the directory, which sits after the lump data"
    directory at infoTableOfs WadLump[numLumps] "every lump in the patch, in load order"
}

// WebAssembly binary module — every section size, vector count and index in the
// format is an LEB128 varint, so nothing sits at a fixed offset. Sections whose
// id is not decoded below are left as raw bytes.

struct Wasm {
    magic    bytes[4]       "00 61 73 6d"
    version  u32            "binary format version (1)"
    sections repeat WasmSection "sections run to the end of the module"
}

struct WasmSection {
    id   u8     "0 custom, 1 type, 3 function, 7 export, 10 code"
    size varint "section length in bytes (LEB128)"
    body match id {
        1  => WasmTypeSection
        3  => WasmFunctionSection
        7  => WasmExportSection
        10 => WasmCodeSection
        default => bytes[size]
    }
}

struct WasmTypeSection {
    count varint "number of function types"
    types WasmFuncType[count]
}

struct WasmFuncType {
    form     u8     "0x60 marks a function type"
    nparams  varint "number of parameters"
    params   u8[nparams]  "value types: 7f i32, 7e i64, 7d f32, 7c f64"
    nresults varint "number of results"
    results  u8[nresults] "result value types"
}

struct WasmFunctionSection {
    count   varint "number of functions"
    typeIdx varint[count] "type index for each function"
}

struct WasmExportSection {
    count   varint "number of exports"
    exports WasmExport[count]
}

struct WasmExport {
    nameLen varint "length of the export name"
    name    string[nameLen] "the name the host sees"
    kind    u8     "0 func, 1 table, 2 memory, 3 global"
    index   u8     "index into that kind space"
}

struct WasmCodeSection {
    count varint "number of function bodies"
    funcs WasmFuncBody[count]
}

struct WasmFuncBody {
    bodySize varint "byte length of this body"
    body     bytes[bodySize] "locals, instructions, then 0x0b end"
}

// WOFF2 - the web font wrapper every browser prefers, and a much more
// aggressive design than the WOFF it replaced. WOFF compressed each sfnt table
// with zlib and left the rest of the font alone. WOFF2 compresses all the tables
// together as one Brotli stream, and preprocesses the two biggest ones: glyf and
// loca are transformed into a form that compresses better and is rebuilt on
// load. Typical result is a file 30% smaller than the same font as WOFF.
//
// Because the tables are one stream, the table directory cannot store offsets.
// It stores each table's tag and lengths instead, and a reader recovers the
// layout by decompressing and walking in order. The directory entries are also
// variable-length: a flag byte whose low bits index a table of 63 well-known
// tags (so common tags cost one byte, not five), then UIntBase128 lengths. That
// makes the directory unwalkable by a declarative schema, so this pack decodes
// the fixed 48-byte header, which is where the sizes and the metadata pointers
// live.
//
// totalSfntSize is the size of the font once rebuilt, and it is a promise: a
// reader may allocate exactly that much before decompressing. flavor says what
// it will rebuild into - 0x00010000 for TrueType outlines, the tag OTTO for
// PostScript ones.

struct Woff2 {
    signature          char[4] "wOF2"
    flavor             u32     "sfnt version of the font inside: 0x00010000 for TrueType, OTTO for CFF"
    length             u32     "total size of this file in bytes"
    numTables          u16     "tables in the directory that follows"
    reserved           u16     "reserved, zero"
    totalSfntSize      u32     "size of the rebuilt, uncompressed font"
    totalCompressedSize u32    "size of the Brotli stream holding every table"
    majorVersion       u16     "font revision, major"
    minorVersion       u16     "font revision, minor"
    metaOffset         u32     "offset of the compressed XML metadata block, 0 if absent"
    metaLength         u32     "compressed length of that block"
    metaOrigLength     u32     "length of the metadata once decompressed"
    privOffset         u32     "offset of the private data block, 0 if absent"
    privLength         u32     "length of the private data block"
    // The table directory follows: numTables entries of a flag byte, an optional
    // 4-byte tag, and UIntBase128 lengths - then the Brotli stream itself.
}

// XZ (.xz) — a 12-byte stream header, blocks, an index, and a stream footer.
// Each block starts with a header whose size is encoded in its first byte
// ((byte + 1) * 4) and which lists the filter chain (usually just LZMA2, id
// 0x21). Multi-byte integers in block headers are variable-length: 7 bits
// per byte with a continuation high bit — LEB128, so varint here.
//
// The compressed size is optional in the block header and single-threaded xz
// leaves it out, so the block data cannot be stepped over in general; this
// pack decodes the stream header and the first block header.

enum XzCheck : u8 {
    None   = 0x00
    Crc32  = 0x01
    Crc64  = 0x04
    Sha256 = 0x0A
}

bitfield XzBlockFlags : u8 {
    numFiltersMinus1        0..1 // number of filters - 1 (1..4 filters)
    reserved                2..5
    compressedSizePresent   6    // a compressed size follows
    uncompressedSizePresent 7    // an uncompressed size follows
}

// One filter in the chain: id, then its properties.
struct XzFilterFlags {
    filterId  varint "0x21 LZMA2, 0x03 delta, 0x04 x86 BCJ, 0x05 PowerPC, 0x06 IA-64, 0x07 ARM, 0x08 ARM-Thumb, 0x09 SPARC, 0x0A ARM64, 0x0B RISC-V"
    propsSize varint "size of the properties"
    props     bytes[propsSize] "filter properties (LZMA2: one byte encoding the dictionary size)"
}

struct XzStreamHeader {
    magic       bytes[6] "FD 37 7A 58 5A 00"
    flagsHigh   u8       "stream flags high byte (always 0)"
    check       XzCheck  "integrity check type used by every block"
    crc32       u32      "CRC-32 of the two stream flag bytes"
}

struct XzBlockHeader {
    sizeByte         u8           "block header size = (this + 1) * 4; 0x00 would mean the index instead"
    headerSize       = (sizeByte + 1) * 4
    flags            XzBlockFlags "filter count and which sizes are present"
    compressedSize   varint if flags.compressedSizePresent   "compressed size of the block data"
    uncompressedSize varint if flags.uncompressedSizePresent "uncompressed size of the block data"
    filter1          XzFilterFlags "first filter"
    filter2          XzFilterFlags if flags.numFiltersMinus1 > 0 "second filter"
    filter3          XzFilterFlags if flags.numFiltersMinus1 > 1 "third filter"
    filter4          XzFilterFlags if flags.numFiltersMinus1 > 2 "fourth filter"
    // Padding (zeros) runs up to the CRC, which is the last 4 bytes of the header.
    crcPos           = headerSize - 4
    crc32            at +crcPos u32 "CRC-32 of the block header"
    raw              at +0 bytes[headerSize] "the whole block header"
}

struct Xz {
    streamHeader XzStreamHeader "stream header"
    firstBlock   XzBlockHeader  "first block header; its compressed data follows"
}

// ZIP — a flat stream of records, each introduced by a 4-byte "PK" signature.
// Local file headers (with their compressed data) come first, then the central
// directory, then the end-of-central-directory record that a reader seeks to
// first. Walking forward from offset 0 works because every local header carries
// its own compressed size.
//
// One caveat: when the dataDescriptor flag is set, a streaming writer left the
// sizes and CRC zero in the local header and wrote them in a descriptor record
// *after* the data. The walk cannot recover from that without scanning, so an
// archive written that way stops at the first such entry.
//
// This is also the container behind jar, apk, docx, xlsx, epub and odt.

enum ZipMethod : u16 {
    Stored    = 0
    Shrunk    = 1
    Imploded  = 6
    Deflate   = 8
    Deflate64 = 9
    Bzip2     = 12
    Lzma      = 14
    Zstd      = 93
    Xz        = 95
    Jpeg      = 96
    WavPack   = 97
    Ppmd      = 98
    AesCrypt  = 99
}

bitfield ZipFlags : u16 {
    encrypted        0  // entry is traditional PKWARE-encrypted
    compressOption1  1  // meaning depends on the method (deflate level)
    compressOption2  2
    dataDescriptor   3  // sizes/CRC are zero here and follow the data
    enhancedDeflate  4
    patchedData      5
    strongEncryption 6
    utf8Names        11 // the name and comment are UTF-8, not CP437
    maskedLocalInfo  13 // local header fields hidden (strong encryption)
}

// A local file header, immediately followed by that file's compressed bytes.
struct ZipLocalFile {
    versionNeeded    u16       "minimum version needed to extract, times 10"
    flags            ZipFlags  "general purpose bit flags"
    method           ZipMethod "compression method"
    modTime          u16       "last modification time (MS-DOS packed)"
    modDate          u16       "last modification date (MS-DOS packed)"
    crc32            u32       "CRC-32 of the uncompressed data"
    compressedSize   u32       "bytes stored (0xFFFFFFFF means see the Zip64 extra)"
    uncompressedSize u32       "bytes after decompression"
    nameLen          u16       "length of the file name"
    extraLen         u16       "length of the extra field"
    name             string[nameLen] "file name, '/' separated, no leading slash"
    extra            bytes[extraLen] "extra field: Zip64 sizes, timestamps, unix ids"
    data             bytes[compressedSize] "the compressed file data"
}

// A central directory entry — one per file, repeating the local header and
// adding the attributes and the offset a reader jumps to.
struct ZipCentralFile {
    versionMadeBy     u16       "creator version; the high byte is the host OS"
    versionNeeded     u16       "minimum version needed to extract, times 10"
    flags             ZipFlags  "general purpose bit flags"
    method            ZipMethod "compression method"
    modTime           u16       "last modification time (MS-DOS packed)"
    modDate           u16       "last modification date (MS-DOS packed)"
    crc32             u32       "CRC-32 of the uncompressed data"
    compressedSize    u32       "bytes stored"
    uncompressedSize  u32       "bytes after decompression"
    nameLen           u16       "length of the file name"
    extraLen          u16       "length of the extra field"
    commentLen        u16       "length of the file comment"
    diskStart         u16       "disk this file starts on (0 unless split)"
    internalAttrs     u16       "bit 0 marks the entry as text"
    externalAttrs     u32       "host attributes; unix mode in the high 16 bits"
    localHeaderOffset u32       "offset of this file's local header"
    name              string[nameLen]    "file name"
    extra             bytes[extraLen]    "extra field"
    comment           string[commentLen] "per-file comment"
}

// End of central directory — the record readers find by scanning backwards.
struct ZipEndOfCentralDir {
    diskNumber      u16 "number of this disk"
    centralDirDisk  u16 "disk holding the start of the central directory"
    entriesThisDisk u16 "central directory entries on this disk"
    entriesTotal    u16 "central directory entries in total"
    centralDirSize  u32 "size of the central directory in bytes"
    centralDirOffset u32 "offset of the first central directory entry"
    commentLen      u16 "length of the archive comment"
    comment         string[commentLen] "archive comment"
}

// Zip64 end of central directory, used once a count or offset overflows 32 bits.
struct Zip64EndOfCentralDir {
    recordSize       u64 "size of this record, these 12 bytes not counted"
    versionMadeBy    u16 "creator version"
    versionNeeded    u16 "minimum version needed to extract"
    diskNumber       u32 "number of this disk"
    centralDirDisk   u32 "disk holding the start of the central directory"
    entriesThisDisk  u64 "central directory entries on this disk"
    entriesTotal     u64 "central directory entries in total"
    centralDirSize   u64 "size of the central directory in bytes"
    centralDirOffset u64 "offset of the first central directory entry"
}

struct Zip64Locator {
    endRecordDisk   u32 "disk holding the Zip64 end-of-central-directory record"
    endRecordOffset u64 "offset of that record"
    totalDisks      u32 "total number of disks"
}

// Written after the data when the dataDescriptor flag is set.
struct ZipDataDescriptor {
    crc32            u32 "CRC-32 of the uncompressed data"
    compressedSize   u32 "bytes stored"
    uncompressedSize u32 "bytes after decompression"
}

struct ZipRecord {
    signature u32 "0x04034B50 local file, 0x02014B50 central, 0x06054B50 end"
    body match signature {
        0x04034B50 => ZipLocalFile
        0x02014B50 => ZipCentralFile
        0x06054B50 => ZipEndOfCentralDir
        0x06064B50 => Zip64EndOfCentralDir
        0x07064B50 => Zip64Locator
        0x08074B50 => ZipDataDescriptor
        default    => bytes[0]
    }
}

struct Zip {
    records repeat ZipRecord until signature == 0x06054B50 "every record, ending at the end-of-central-directory"
}

// Zstandard (RFC 8878) — one or more frames, each a magic number, a frame
// header, blocks, and an optional checksum. The frame header is variable:
// the descriptor byte says which of the optional fields are present and how
// wide the content size is.
//
// Block headers are 3 bytes: bit 0 last-block, bits 1-2 type, bits 3-23 size.
// For an RLE block the size is the decompressed size and the block content is
// a single byte; for raw and compressed blocks the size is the content length,
// so the walk can step over every block to the end of the frame.

bitfield ZstdFrameDescriptor : u8 {
    dictIdFlag           0..1 // dictionary id width: 0 none, 1 = 1 byte, 2 = 2 bytes, 3 = 4 bytes
    contentChecksum      2    // a 4-byte XXH64 checksum ends the frame
    reserved             3
    unused               4
    singleSegment        5    // no window descriptor; content size is present
    frameContentSizeFlag 6..7 // content size width: 0 = 0/1 byte, 1 = 2 bytes, 2 = 4 bytes, 3 = 8 bytes
}

bitfield ZstdWindowDescriptor : u8 {
    mantissa 0..2 // window size = (1 << (exponent + 10)) * (1 + mantissa / 8)
    exponent 3..7
}

bitfield ZstdBlockHeaderLow : u8 {
    lastBlock 0    // this is the last block of the frame
    blockType 1..2 // 0 raw, 1 RLE, 2 compressed, 3 reserved
    sizeLow   3..7 // low 5 bits of the block size
}

struct ZstdBlock {
    header    ZstdBlockHeaderLow "last-block bit, block type, low size bits"
    sizeMid   u8
    sizeHigh  u8
    blockSize = header.sizeLow + sizeMid * 32 + sizeHigh * 8192
    // Raw and compressed blocks carry blockSize bytes; an RLE block carries
    // the one byte that is repeated blockSize times.
    content   bytes[blockSize] if header.blockType == 0 "raw (stored) block content"
    rleByte   u8               if header.blockType == 1 "byte repeated blockSize times"
    compressed bytes[blockSize] if header.blockType == 2 "compressed block: literals section then sequences section"
}

struct ZstdFrame {
    magic            u32                  "0xFD2FB528"
    descriptor       ZstdFrameDescriptor  "which optional header fields follow"
    windowDescriptor ZstdWindowDescriptor if descriptor.singleSegment == 0 "decoder window size"
    dictId8          u8  if descriptor.dictIdFlag == 1 "dictionary id"
    dictId16         u16 if descriptor.dictIdFlag == 2 "dictionary id"
    dictId32         u32 if descriptor.dictIdFlag == 3 "dictionary id"
    // Content size: width from the flag; with flag 0 it is one byte, present
    // only in single-segment frames.
    fcsCase          = descriptor.frameContentSizeFlag * 2 + descriptor.singleSegment
    contentSize8     u8  if fcsCase == 1 "decompressed size"
    contentSize16    u16 if descriptor.frameContentSizeFlag == 1 "decompressed size minus 256"
    contentSize32    u32 if descriptor.frameContentSizeFlag == 2 "decompressed size"
    contentSize64    u64 if descriptor.frameContentSizeFlag == 3 "decompressed size"
    blocks           repeat ZstdBlock until header.lastBlock "every block of the frame"
    checksum         u32 if descriptor.contentChecksum "low 32 bits of the XXH64 of the decompressed content"
}

struct Zstd {
    frames repeat ZstdFrame "concatenated frames (usually just one)"
}
